insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('separation', 'advanced', 'module', 'm01-three-phases-in-one-vessel', 1, 'AGBAMI carries 12000.000000 bpd of oil held 5.000000 minutes and 8000.000000 bpd of water held 8.000000 minutes, and the engine gives the water 0.516129 of the liquid cross-section. Where does that share come from?', '["The water cut arriving at the inlet, which is 8000.000000 bpd of the 20000.000000 bpd of liquid, scaled by the level of 0.500000.", "The ratio of the two specific gravities, since the denser phase settles into the larger band once the level fixes the liquid area.", "Duty, which is a rate times a retention time: the water asks for 8000.000000 times 8.000000 barrel-minutes against the oil''s 12000.000000 times 5.000000.", "The water area of 20.268340 ft2 divided by the gas-liquid chord of 10.000000 ft, which is the width the liquid surface spans across the drum at a level of 0.500000."]'::jsonb, 2, 'Rate alone would have given the water 0.400000 of the cross-section. The extra water retention moved the share to 0.516129, which is the whole point of a retention-proportional rule.'),
  ('separation', 'advanced', 'module', 'm01-three-phases-in-one-vessel', 2, 'The water area on AGBAMI is 20.268340 ft2 in a drum 10.000000 ft across. How does the engine turn that area into an interface height of 3.049149 ft?', '["It asks which depth in the circle produces a segment of exactly 20.268340 ft2, and bisects until it has it.", "It divides 20.268340 ft2 by the gas-liquid chord of 10.000000 ft, which is the width of the liquid surface at a level of 0.500000 and the divisor the engine used before FC1-0.", "It gives the water the same fraction of the liquid depth of 5.000000 ft that it gave of the liquid area, so the share of 0.516129 places the interface directly.", "It divides the water retention volume by the liquid area of 39.269908 ft2 and reads the result as a depth, because a volume over an area is a length in ft."]'::jsonb, 0, 'The chord rule gives 2.026834 ft on this vessel against the exact 3.049149 ft. A segment narrows toward the bottom of the drum, so one width overstates the area a given thickness can hold.'),
  ('separation', 'advanced', 'module', 'm01-three-phases-in-one-vessel', 3, 'Across the published three-phase cases every retired chord-rule water layer sits below the exact figure. Why does that error never change sign?', '["The bisection stops after 100 iterations and truncates, so the retired figure is the same answer rounded down on every published case.", "The chord is the widest line the liquid has across the drum, and a segment narrows steadily downward, so dividing an area by that single width always understates the thickness the area really takes up.", "The retired rule divided the oil area of 19.001568 ft2 rather than the water area, and the oil area is the smaller of the two.", "Every published case runs at a liquid level of 0.500000, where the chord is the full diameter of 10.000000 ft and is the largest width available."]'::jsonb, 1, 'On thickOilWaterCarryover the retired water layer is 3.020762 ft against the exact 4.088701 ft, and on lowLevelSmallOilDropCarryunder it is 0.617770 ft against 1.249328 ft at a level of 0.300000.'),
  ('separation', 'advanced', 'module', 'm01-three-phases-in-one-vessel', 4, 'Pinning the AGBAMI water share at 0.300000 takes the vessel from 12.311666 ft to 21.181362 ft. Why does a thinner water band produce a longer drum?', '["The pin enlarges the gas space above the liquid, so gas capacity takes the length over from liquid retention and sets it at 21.181362 ft on a drum 10.000000 ft across.", "The oil layer grows to 2.925687 ft and the oil is the larger stream at 12000.000000 bpd, so the oil sets the requirement once the interface has dropped to 2.074313 ft.", "A pinned share makes the engine take the largest retention length on file rather than sizing this drum.", "The water still owes 8.000000 minutes, and a smaller cross-section buys that time only with length: it asks 21.181362 ft against the oil''s 8.510368 ft."]'::jsonb, 3, 'retentionPhase reads water. The pin starved the phase with the longest retention time of cross-section, and the drum had to grow lengthways to hand back the 8.000000 minutes.'),
  ('separation', 'advanced', 'module', 'm01-three-phases-in-one-vessel', 5, 'On the proportional AGBAMI case phaseRetentionLengthsFt and retentionPhase both come back null. What is the engine reporting?', '["That the split was built to make the two phase lengths agree, so no contest was held and there is no second length to print.", "That the two phase lengths tied inside the relative gap of 1e-9 the constant RETENTION_TIE_REL allows, which is the one situation where the phase field is suppressed.", "That the controlling requirement on this row was gas rather than liquid retention, so a retention phase has no meaning here and both fields are blanked together.", "That the oil and the water were given equal retention times, which leaves neither phase able to claim the requirement of 12.311666 ft as its own."]'::jsonb, 0, 'One liquid retention requirement of 12.311666 ft comes back. A genuine tie inside 1e-9 also leaves retentionPhase null, and that is a different situation from a split that produced one length by construction.'),
  ('separation', 'advanced', 'module', 'm01-three-phases-in-one-vessel', 6, 'gasOverloaded6ftGasControls reports a retention requirement of 0.689497 ft, a length of 16.976527 ft, controlling gas and retentionPhase null. What do those fields say together?', '["The gas requirement of 16.976527 ft was produced by the water phase, so retentionPhase is left null rather than naming the water twice.", "Liquid retention was never computed here, so 0.689497 ft is a figure carried across from the two-phase path and the phase field has nothing to report.", "Gas capacity beat liquid retention for the length of 16.976527 ft, and inside liquid retention, which asked only 0.689497 ft, no phase had to be named at all.", "Each phase needed 0.689497 ft and the gas needed the remainder, which is why the retention figure is the smaller and why no phase is named."]'::jsonb, 2, 'Two contests run on a three-phase row. Liquid retention against gas capacity sets the length, and here gas won it at 16.976527 ft; oil against water inside liquid retention was never held.'),
  ('separation', 'advanced', 'module', 'm01-three-phases-in-one-vessel', 7, 'A reviewer reports the AGBAMI water cut as 0.516129. Which figure did they want, and what does 0.516129 actually describe?', '["They wanted 0.300000, the share an interface controller would be pinned at, and 0.516129 is the fraction of the liquid depth of 5.000000 ft that the water band fills.", "They wanted 0.400000, the 8000.000000 bpd of water in 20000.000000 bpd of liquid; 0.516129 is the share of cross-section the retentions ask for.", "They wanted 0.285714, the water share on the published low level case, and 0.516129 is a fraction of the diameter.", "Both figures describe one quantity and 0.516129 is the more exact, since it is built from the rates and the retention times."]'::jsonb, 1, 'The two agree only where the retention times are equal. The water is held 8.000000 minutes against the oil''s 5.000000, so the cross-section share of 0.516129 sits above the rate share of 0.400000.'),
  ('separation', 'advanced', 'module', 'm01-three-phases-in-one-vessel', 8, 'A two-phase habit brings a single dropletMicron argument to a three-phase call. What happens?', '["The figure is accepted and applied to both checks, which is what the argument meant before the two droplet sizes were separated out of it into their own inputs.", "An object comes back carrying an error string, because one size standing for two directions is a fair question that this method has no answer for.", "A SeparatorInputError on waterDropletMicron, the first size the engine looks for.", "A SeparatorInputError on dropletMicron, with a message naming waterDropletMicron and oilDropletMicron as the two replacements."]'::jsonb, 3, 'A water drop falls through oil and an oil drop rises through water, so the two checks carry different sizes, directions and layers. The message names the replacements rather than reporting an unknown argument.'),
  ('separation', 'advanced', 'module', 'm01-three-phases-in-one-vessel', 9, 'A missing qOilBpd throws, while gravities the wrong way round inside a droplet calculation come back as an object carrying an error string. Why the two shapes?', '["A throw says the caller left out something it was required to supply, while an error object says the question asked was fair and this method has no answer for it.", "A throw stops the caller where an error object lets a sweep finish its remaining rows, so the choice is about how much of a family survives one bad input value.", "A throw is reserved for a value outside its domain and an error object for a value that is missing.", "The error object is the newer shape and the throws are the calls FC1-0 has not converted yet."]'::jsonb, 0, 'sgWater (1) must exceed sgOil (1.1) for the water to settle is thrown on a named input, while the heavy phase must be denser than the light phase is returned from a calculation that cannot proceed.'),
  ('separation', 'advanced', 'module', 'm01-three-phases-in-one-vessel', 10, 'explicit25pctWaterWaterRetentionSets pins the water at 0.250000 of the liquid area and reports retentionPhase water with a length of 7.943011 ft. What made the water the named phase?', '["Its retention time is the longer of the two, and the longer retention time names the phase on every pinned case whatever share the interface controller was set to.", "The pinned share of 0.250000 sits below the share the retentions would have produced, and the engine names whichever phase the pin squeezed without comparing lengths.", "Its band is the thinner at an interface of 1.826477 ft under 3.173523 ft of oil, and a thin band needs more length to hold its retention time.", "The water is the denser phase and lies along the bottom of the drum, so a length is always measured in the water band and the field records which band it was measured in."]'::jsonb, 2, 'The requirement is the larger of the two phase lengths, 7.943011 ft here. The AGBAMI pin at 0.300000 names the water for the same reason, 21.181362 ft against the oil''s 8.510368 ft.'),
  ('separation', 'advanced', 'module', 'm01-three-phases-in-one-vessel', 11, 'thickOilWaterCarryover holds 0.769231 of its liquid area as water, with an interface at 4.088701 ft and an oil layer of 0.911299 ft in a drum 10.000000 ft across at a level of 0.500000. What did the retired chord rule report on that same vessel?', '["A water layer of 4.088701 ft and an oil layer of 0.911299 ft, because at a level of 0.500000 the chord is the full diameter and the two rules land on the same answer there.", "A water layer of 2.026834 ft, which is what the chord rule returns on any drum 10.000000 ft across at a level of 0.500000, whatever share the two retentions produced.", "A water layer of 1.570796 ft under an oil layer of 2.356194 ft, which are the chord-rule figures for a 10.000000 ft drum held at a liquid level of 0.500000.", "A water layer of 3.020762 ft and an oil layer of 0.906229 ft."]'::jsonb, 3, 'The chord rule understates the water layer on every case, here by more than a foot, and its two layers do not have to add back to the liquid depth of 5.000000 ft the way the exact ones do.'),
  ('separation', 'advanced', 'module', 'm01-three-phases-in-one-vessel', 12, 'A drum 8.000000 ft across at a level of 0.350000 has a liquid depth of 2.800000 ft and an area of 15.678751 ft2, and feeding that area back returns 2.800000 ft. What is being shown?', '["Segment area runs linearly with depth below a level of 0.500000, which is why the figure comes back unchanged and why the chord rule was adequate on shallow liquid levels.", "The area to depth inversion is exact to double precision, so a depth turned into an area and then back into a depth comes out as the depth it started from.", "The bisection leaves an error too small to see at 8.000000 ft, so the round trip measures that tolerance.", "The level of 0.350000 and the diameter of 8.000000 ft put 15.678751 ft2 on a bisection boundary."]'::jsonb, 1, 'The engine bisects 100 times and the depth returns unchanged, which is what lets an interface of 3.049149 ft be quoted to six decimals rather than to the nearest inch.'),
  ('separation', 'advanced', 'module', 'm01-three-phases-in-one-vessel', 13, 'An interface controller setpoint arrives as a water share of exactly 0. What does three-phase sizing do with it?', '["It throws a SeparatorInputError on waterFracOfLiquid, saying the share must lie strictly between 0 and 1 when it is given at all.", "It falls back to the retention-proportional split, which is what happens whenever a pin cannot be honoured, and sizes AGBAMI at 12.311666 ft as though no pin had arrived.", "It clamps the share to a small positive value so the area inversion has something to work on, and records the clamp in the warning field beside the result it returns.", "It returns an object carrying an error string, because a drum with no water band is a state with no answer."]'::jsonb, 0, 'A vessel with no water band is a two-phase vessel and should be sized as one. There is no clamp and no fallback, and a share of exactly 1 is refused in the same words.'),
  ('separation', 'advanced', 'module', 'm01-three-phases-in-one-vessel', 14, 'A reviewer fixes the AGBAMI interface where they want it and then opens an argument about the retention times. What is wrong with that order of work?', '["Nothing, provided the pin is recorded on the datasheet, since a pinned share of 0.300000 and the proportional share of 0.516129 both size AGBAMI at 12.311666 ft.", "The interface cannot be placed until the length is known, because the vessel length of 12.311666 ft fixes the areas that the water share of 0.516129 then divides between the phases.", "The share follows from the retentions, so raising the water retention above 8.000000 minutes widens the water band and lifts the interface.", "A pinned interface takes the droplet verdicts out of the result, so the retention times cannot be argued about."]'::jsonb, 2, 'Pinning is allowed and it is priced: the pin at 0.300000 took AGBAMI from 12.311666 ft to 21.181362 ft. What cannot be done is to treat a derived share as an input and reason back to the retentions.'),
  ('separation', 'advanced', 'module', 'm01-three-phases-in-one-vessel', 15, 'Before FC1-0 a three-phase call with no oil gravity still produced two droplet verdicts. What were they, and why is that worse than a refusal?', '["Both came back true, which sent designers away to widen vessels that were already adequate, so the defect cost money rather than costing safety on the plant.", "Both came back false, which is the word this engine uses for a vessel that passed, so a run with no density difference to work from read as a clean result.", "Both came back null, which a caller rendering a boolean showed as a blank cell for a reviewer to fill in by eye.", "Only the carryunder verdict came back, because the water gravity was present and the rising drop leans on that one."]'::jsonb, 1, 'The repair is a refusal by name, a SeparatorInputError on sgOil. A verdict for an input the engine could not read said nothing, and it said nothing in the reassuring direction.'),
  ('separation', 'advanced', 'module', 'm02-droplets-and-verdicts', 1, 'The Stokes oracle sits at 1.004184 times the engine on stokes500um, stokes150um and stokes1000um, in the same direction each time. What does that pattern establish?', '["That the oracle carries a unit conversion the engine does not, which is the one explanation left once three cases at three droplet sizes and three viscosities agree to six decimals on the ratio.", "That the engine is wrong by four parts in a thousand and the goldens record the error, so any case decided inside that gap has to be re-run against the SI form before anybody quotes it.", "That the two implementations disagree about the density difference, since specific gravity in the field form and density in SI are the only inputs the two forms take in different units.", "A packaged constant rather than an arithmetic slip, since a slip in the working would move with the inputs and this gap does not."]'::jsonb, 3, 'The field constant 1.78e-6 is a rounded packaging of the SI group g d2 dRho over 18 mu. The engine reads 0.044500 ft/s where the oracle reads 0.044686 ft/s, always low and always by the same ratio.'),
  ('separation', 'advanced', 'module', 'm02-droplets-and-verdicts', 2, 'Where does the four parts in a thousand between the field form and the SI derivation actually matter to a verdict?', '["Only where a crossing time and a residence time nearly meet, which is why any gate on droplet settling has to hold a tolerance wider than the 1.004184 the three published cases show.", "On every verdict, since the engine velocity of 0.001762 ft/s on stokes150um is the figure the comparison uses and it sits low against the oracle''s 0.001770 ft/s.", "On the large drops, because the gap scales with the square of the droplet size and 1000.000000 micron carries it on 0.320400 ft/s rather than on 0.044500 ft/s.", "On the carryunder check alone, because a rising oil drop crosses the thicker of the two layers and a small velocity error accumulates over that distance."]'::jsonb, 0, 'A drop needing 111.4796 s in a phase that stays 300.0000 s is nowhere near the edge. The ratio is the same 1.004184 at every size, so the margin decides whether it bites.'),
  ('separation', 'advanced', 'module', 'm02-droplets-and-verdicts', 3, 'A 500.000000 micron water drop settles at 0.017500 ft/s in 4.000000 cP oil. What does the same oil do to a 250.000000 micron drop?', '["0.008750 ft/s, half the 500.000000 micron figure, because a linear reading of the law makes the velocity fall in proportion to the droplet diameter at a fixed viscosity of 4.000000 cP.", "0.001575 ft/s, which is what the same oil gives at 150.000000 micron and the smallest velocity the table carries for a water drop in oil.", "0.004375 ft/s, a quarter of the speed, because the settling velocity goes as the square of the droplet size.", "0.017500 ft/s still, since the size sets the distance and the viscosity sets the speed."]'::jsonb, 2, 'The table runs 0.017500, 0.008575, 0.004375, 0.001575 and 0.000700 ft/s at 500.000000, 350.000000, 250.000000, 150.000000 and 100.000000 micron. Halving the drop quarters the speed.'),
  ('separation', 'advanced', 'module', 'm02-droplets-and-verdicts', 4, 'On AGBAMI a water drop is judged against 300.0000 s and an oil drop against 480.0000 s. Why those two figures rather than one of them for both?', '["The shorter residence is applied to the harder check and the longer one to the easier check, so the falling drop that has 111.4796 s of work in front of it takes 300.0000 s.", "Each drop races the phase it is trying to leave: the falling water drop races the oil, and the rising oil drop races the water.", "The oil is the product stream and is judged first at 300.0000 s, and the water is given whatever residence is left.", "Each drop is judged against the phase it ends up in, so a water drop that has fallen takes the water''s 480.0000 s."]'::jsonb, 1, 'The water drop crosses 1.950851 ft of oil in 111.4796 s against the oil''s 300.0000 s, and the oil drop crosses 3.049149 ft of water in 217.8010 s against the water''s 480.0000 s.'),
  ('separation', 'advanced', 'module', 'm02-droplets-and-verdicts', 5, 'Tightening the AGBAMI water specification from 500.000000 micron to 150.000000 micron turns waterCarryover true. What else moves?', '["The vessel length, which rises from 12.311666 ft because the engine lengthens the drum until the oil residence covers the crossing time of 1238.6620 s the smaller drop needs.", "The interface, which drops below 3.049149 ft because the tighter specification asks for a thinner oil layer and the engine places the interface to give the drop less to cross.", "The oil residence, which rises above 300.0000 s once the tighter specification is applied, because residence is recomputed against the droplet size the vessel is asked to remove.", "Nothing else: the drum, the layers, the residence times and the length stand exactly where they were."]'::jsonb, 3, 'The drop falls at 0.001575 ft/s instead of 0.017500 ft/s and needs 1238.6620 s against the same 300.0000 s of residence. A droplet size is a product specification and it sizes nothing by itself.'),
  ('separation', 'advanced', 'module', 'm02-droplets-and-verdicts', 6, 'The engine''s carryover warning offers two repairs: raise the oil retention, or lower the interface. What does each one do to the comparison?', '["Raising the retention lengthens the drum and buys residence time directly, while lowering the interface thins the oil layer and shortens the crossing the drop has to make.", "Raising the retention thins the oil layer by handing the water more of the cross-section, and lowering the interface buys residence time by slowing the oil stream down as it moves through the drum.", "Both of them lengthen the vessel past 12.311666 ft, since the retention time and the interface height are the two inputs the liquid retention length is built from.", "Raising the retention widens the water band and lowering the interface widens it further, so both act on the layer the falling drop crosses."]'::jsonb, 0, 'The message is verbatim about this case: 1238.6620 s to fall through the 1.95 ft oil layer against 300.0000 s of residence. Neither lever touches the droplet size, which says how clean the oil must be.'),
  ('separation', 'advanced', 'module', 'm02-droplets-and-verdicts', 7, 'A designer cures a water carryover by lowering the interface. What should they check next?', '["The gas capacity margin, because moving the interface down raises the liquid level and takes gas space out of the top of the drum where settling is measured.", "The oil residence time, because the oil layer has thinned and a thinner band carries the same oil rate through the drum faster than a thick one does.", "The carryunder verdict, because a lower interface thickens the water layer the rising oil drop has to cross.", "The retention phase field, because a lower interface makes the oil the phase that sets the requirement."]'::jsonb, 2, 'AGBAMI holds 1.950851 ft of oil over 3.049149 ft of water. The two verdicts pull in opposite directions, so a vessel can be walked out of one failing check straight into the other.'),
  ('separation', 'advanced', 'module', 'm02-droplets-and-verdicts', 8, 'Under the retention-proportional split the AGBAMI residences come back as 300.0000 s and 480.0000 s. Why does this course decline to grade those two figures?', '["They depend on the droplet sizes that were asked for, so they move whenever the specification moves and cannot be marked against any fixed expected value at all.", "They are the retention times somebody typed in, 5.000000 minutes and 8.000000 minutes, converted to seconds.", "They come from the vessel length of 12.311666 ft, which may be revised.", "They print to four decimals where vessel work runs to six."]'::jsonb, 1, 'The proportional split was built to give both phases the same length, so each phase gets exactly the time it was designed for. Quoting one back is quoting an input.'),
  ('separation', 'advanced', 'module', 'm02-droplets-and-verdicts', 9, 'Pin the AGBAMI water share at 0.300000 and the oil residence becomes 746.6667 s while the water stays at 480.0000 s. Why did one move and the other not?', '["The water set the length at 21.181362 ft to buy its own 8.000000 minutes, and the oil was left sitting in a band of 2.925687 ft inside a drum that had been sized for somebody else.", "The pin raised the oil rate through the drum and left the water rate alone, so only the oil residence had to be recomputed after the interface moved to 2.074313 ft.", "The water residence is fixed by the retention time of 8.000000 minutes in every case, pinned or proportional, while the oil residence is always computed.", "The oil band grew to 2.925687 ft and the water band shrank to 2.074313 ft, and residence scales with band thickness, so the two moved in opposite directions."]'::jsonb, 0, 'This is where a residence becomes a real output rather than an input read back. The oil is held far longer than its own 5.000000 minutes asked for, because another phase forced the length.'),
  ('separation', 'advanced', 'module', 'm02-droplets-and-verdicts', 10, 'A report gives waterCarryover false for a three-phase vessel and no droplet size. What is missing from that claim?', '["The residence time it was compared against, which is the only figure that can turn a verdict and cannot be recovered from the vessel dimensions once a report has been issued.", "The direction of the check, since waterCarryover and oilCarryunder both read false on a passing vessel and cannot be told apart without the layer thickness printed beside them.", "The oracle velocity, because a verdict quoted from the field form of Stokes law sits four parts in a thousand from the SI figure and that gap belongs beside any published verdict.", "Its premise: false says a drop of the stated size crossed in time, and it says nothing about a smaller one."]'::jsonb, 3, 'AGBAMI clears at 500.000000 micron with 111.4796 s against 300.0000 s, and fails at 150.000000 micron with 1238.6620 s against the same residence. The vessel is identical in both runs.'),
  ('separation', 'advanced', 'module', 'm02-droplets-and-verdicts', 11, 'Before FC1-0 the carryunder check measured the rising oil drop against a water layer of 2.026834 ft on AGBAMI where the vessel holds 3.049149 ft. Which way did that error run?', '["Conservative: a thinner layer leaves the drop less time inside the water band, so the check failed vessels that would in fact have separated the stream cleanly enough.", "Permissive: a thinner layer is crossed sooner, so the check came back with room the vessel does not give.", "Neither, because the same chord divisor was applied to the oil layer too and the two errors cancel.", "It depended on the level, since the chord equals the diameter only at a level of 0.500000."]'::jsonb, 1, 'The arithmetic was honest and the geometry handed to it was not. On lowLevelSmallOilDropCarryunder the retired layer is 0.617770 ft against the exact 1.249328 ft, less than half of it.'),
  ('separation', 'advanced', 'module', 'm02-droplets-and-verdicts', 12, 'A three-phase run before FC1-0 was given no oil gravity and reported waterCarryover false and oilCarryunder false. What had actually happened?', '["The engine substituted a default oil gravity taken from the published cases, sized the vessel on it, and reported the verdicts that default produced without flagging it.", "The engine skipped both droplet checks and returned the initialised values of the two fields, which a caller could detect from the empty warning string beside them.", "Both calculations read NaN, every comparison against NaN came back false, and false is the word for a vessel that passed.", "The engine fell back to the water gravity for both phases, leaving a density difference of zero."]'::jsonb, 2, 'Nothing was computed. A Stokes velocity needs a density difference, and a difference taken against a gravity the engine could not read is NaN, so both crossing times were NaN as well.'),
  ('separation', 'advanced', 'module', 'm02-droplets-and-verdicts', 13, 'A NaN gravity read as a passing comparison, a chord-rule water layer and one dropletMicron standing for two checks. What do the three retired behaviours have in common?', '["Not one of them ever raised a false alarm, so each was quiet in exactly the way a defect that fails open is quiet and stayed in the engine until somebody went looking.", "Each was confined to the carryunder check, which is why the carryover verdict came through FC1-0 unchanged and only the rising drop had to be re-run.", "Each produced a number out by a constant factor, so a result from before the repair can be scaled to the right answer without running the case again.", "Each was caught by the published goldens as soon as the oracle was written, which is why the three were repaired together in FC1-0."]'::jsonb, 0, 'A defect that fails closed announces itself the first time somebody sizes a vessel. A green verdict from a method that could fail open is the one to re-run, and it is the one nobody re-runs.'),
  ('separation', 'advanced', 'module', 'm02-droplets-and-verdicts', 14, 'On AGBAMI a 200.000000 micron oil drop rises at 0.014000 ft/s and the water band is 3.049149 ft deep. What does the check report?', '["217.8010 s of crossing against 300.0000 s of residence, so the margin is narrower than the falling drop''s and oilCarryunder still comes back false on the strength of it.", "217.8010 s of crossing against 480.0000 s of water residence, so oilCarryunder comes back false.", "111.4796 s of crossing against 480.0000 s of residence, since both drops cross the liquid depth of 5.000000 ft and differ only in direction.", "1238.6620 s of crossing against 480.0000 s of residence, so oilCarryunder comes back true and the vessel has to be re-sized."]'::jsonb, 1, 'The rising drop is judged against the water it is leaving. Its layer of 3.049149 ft is the thicker of the two, which is why a slower drop still clears with room to spare.'),
  ('separation', 'advanced', 'module', 'm02-droplets-and-verdicts', 15, 'A droplet arrives with no viscosity to fall through, and a separate call has the heavy phase lighter than the light phase. How does settling answer each?', '["With a SeparatorInputError naming muOilCp in the first case and sgWater in the second, since both are named inputs the caller failed to supply correctly.", "With a velocity of zero in the first case and a negative velocity in the second, either of which a caller can test for without reading a message string at all.", "With an object carrying an error string in both cases: settling needs a droplet size and viscosity, and the heavy phase must be denser than the light phase, both returned rather than thrown.", "With an error object in the first case and a throw in the second, since a missing viscosity is an absent input while a reversed pair of gravities is a value outside its domain."]'::jsonb, 2, 'Both are fair questions the method cannot answer, so neither is a throw. The thrown refusals live upstream, on the named inputs a three-phase call has to be given before settling is reached.'),
  ('separation', 'advanced', 'module', 'm03-the-family-of-vessels', 1, 'A sweep returns a preferred diameter. Which tests produce it, and in which order are they applied?', '["Smallest first: the smallest diameter offered is taken and then tested, and a family whose smallest row fails either flag comes back with no preference at all.", "Feasible first, so the vessel carries its gas and clears its droplet verdicts, then inside the band that was passed in, and only then the smallest of whatever survived both of those tests.", "In band first, then the first such row in the order the diameters were supplied, which is the rule the sweep applied before FC1-0.", "Feasible first, then the largest surviving row, so the recommendation carries the most gas margin the vendor list can offer."]'::jsonb, 1, 'ABANA-2 prefers 7.000000 ft with preferredStatus selected. Diameter drives cost and every larger feasible row also works, so smallest is an economic tie-break applied after the engineering tests.'),
  ('separation', 'advanced', 'module', 'm03-the-family-of-vessels', 2, 'ABANA-2 prefers 7.000000 ft in a band of 3.000000 to 5.000000. Why is the 8.000000 ft row passed over when it is feasible?', '["Its length of 23.270539 ft is shorter than the 30.394173 ft of the 7.000000 ft row, and the sweep prefers the longer vessel where both of them carry their gas.", "It is infeasible on gas capacity in the same way as the 5.000000 ft and 6.000000 ft rows, which is what the reason list of ld-out-of-band is recording on that row.", "It sits later in the diameter list than 7.000000 ft, and where two rows both qualify the sweep keeps whichever one it met first while it was walking the list.", "Its slenderness of 2.908817 is below the band, so inRange is false and it never reaches the size comparison."]'::jsonb, 3, 'The 8.000000, 9.000000 and 10.000000 ft rows are all feasible and all below the band at 2.908817, 2.042955 and 1.489314. The 7.000000 ft row at 4.342025 is the only row that clears both tests.'),
  ('separation', 'advanced', 'module', 'm03-the-family-of-vessels', 3, 'Widen the ABANA-2 band from 3.000000 to 5.000000 out to 3.000000 to 7.000000. What changes in the table, and what does the preference do?', '["The 6.000000 ft row becomes inRange true and stays infeasible on gas capacity, so its reason list drops ld-out-of-band and keeps gas-capacity, and the preference holds at 7.000000 ft.", "The 6.000000 ft row becomes inRange true and feasible, and the preference moves down to it because it is the smaller of the two qualifying vessels.", "The 5.000000 ft row at a slenderness of 11.914516 comes into the band as well, and the preference moves to it as the smallest row now in range.", "Nothing changes anywhere in the table, because the band is compared against the slenderness and no slenderness moved."]'::jsonb, 0, 'Preferred stays 7.000000 ft with status selected. A band is an input about shape, so it can move inRange and the reason list, and it can never make a row that fails on gas carry its gas.'),
  ('separation', 'advanced', 'module', 'm03-the-family-of-vessels', 4, 'Before FC1-0 the sweep took the first row inside the band. What would that rule have returned for ABANA-2 once the band was widened to 3.000000 to 7.000000?', '["7.000000 ft, since the retired rule read the feasible flag too.", "5.000000 ft, the first row in the list order.", "6.000000 ft, a vessel that cannot carry its gas, because somebody widened a preference about shape.", "No row at all, because the retired rule refused to answer once more than one row in a family had come into the band it was given."]'::jsonb, 2, 'The 6.000000 ft row is inRange true, feasible false, reasons gas-capacity. That is the test the repair was built to pass, and the repaired answer stays at 7.000000 ft.'),
  ('separation', 'advanced', 'module', 'm03-the-family-of-vessels', 5, 'inRange and feasible are reported as two separate flags. What does each one answer?', '["inRange asks whether the diameter appears in the vendor list that was swept, and feasible asks whether the length that resulted can be fabricated at that diameter.", "inRange asks whether the slenderness sits inside the band that was typed in, and feasible asks whether the vessel carries its gas and clears its droplet verdicts.", "inRange asks whether the vessel works and feasible asks whether it is the shape the plot wants, which is why the 8.000000 ft row reads feasible true.", "Both ask the same question from different ends, which is why every row that is out of band is also infeasible."]'::jsonb, 1, 'The two are independent and all four combinations occur. On ABANA-2 the 8.000000 ft row is feasible and out of band, while the 5.000000 ft row at 11.914516 is neither.'),
  ('separation', 'advanced', 'module', 'm03-the-family-of-vessels', 6, 'A row comes back with reasons gas-capacity and ld-out-of-band. Which of those two set feasible to false?', '["gas-capacity, because it says the vessel failed to do the job, while ld-out-of-band records a preference about shape that was itself an input to the sweep.", "ld-out-of-band, because a slenderness outside the band is the one objection a sweep is asked to enforce, and the band of 3.000000 to 5.000000 is what the plot can physically take.", "Both of them, which is why rows carrying two reasons are the infeasible ones in every published family.", "Neither, since feasible is set from the margin and the reason list is printed beside it for the reader."]'::jsonb, 0, 'The reason vocabulary is gas-capacity, ld-out-of-band, water-carryover and none. On ABANA-2 the 8.000000 ft row carries ld-out-of-band alone and still comes back feasible true.'),
  ('separation', 'advanced', 'module', 'm03-the-family-of-vessels', 7, 'preferredStatus reads selected, none-feasible or none-in-band. What separates the two nulls?', '["none-feasible means the diameter list was empty or refused, and none-in-band means the list was swept and every row came back with a reason attached to it.", "none-feasible means the droplet verdicts failed and none-in-band means gas capacity failed, so the status names which of the two physical tests did the excluding.", "none-feasible means the band was wider than any row could satisfy, and none-in-band means the band was narrower than the vessels the vendor had to offer that day.", "none-feasible means no row works at all, and none-in-band means feasible rows exist and none is shaped the way the band asks."]'::jsonb, 3, 'They call for opposite actions. none-feasible sends the stream, the specification or the diameter list back for change, and none-in-band is an argument about a band somebody typed.'),
  ('separation', 'advanced', 'module', 'm03-the-family-of-vessels', 8, 'The AGBAMI family at 500.000000 micron prefers 7.000000 ft. Tighten the water specification to 150.000000 micron and preferred is null with status none-feasible. What happened to the vessels?', '["Every row grew longer once the tighter specification was applied, and the lengths that resulted pushed all five slendernesses out of the band of 3.000000 to 5.000000.", "The 7.000000 ft row lost its gas margin at the smaller droplet size, so the reason list on it moved from none to gas-capacity and the sweep ran out of feasible rows.", "Nothing happened to the vessels: every row keeps its length and slenderness and every row now carries water-carryover.", "The band was re-judged against the new specification, so rows in range at 3.589407 fell out."]'::jsonb, 2, 'The 7.000000 ft row still runs 25.125850 ft at a slenderness of 3.589407 and is still inRange true. A droplet verdict gates feasibility, because a vessel that carries water over has not separated the stream.'),
  ('separation', 'advanced', 'module', 'm03-the-family-of-vessels', 9, 'Leave the AGBAMI specification at 500.000000 micron and narrow the band to 4.000000 to 5.000000. Preferred is null with status none-in-band. What does that say about the vessels?', '["Two of them work and three do not, which is the mix that produces none-in-band rather than none-feasible, since a family with no working row at all would have reported the other status.", "Every one of them works: all five rows are feasible and all five carry ld-out-of-band alone, so the band asked for a shape none of the offered diameters makes.", "None of them works, since a status of null is only ever returned where the sweep found nothing it could recommend.", "The vessels are untested, because narrowing a band stops the sweep before the feasibility checks are run."]'::jsonb, 1, 'The 7.000000 ft row at 3.589407 was preferred in a band of 3.000000 to 5.000000 and is out of range in a band of 4.000000 to 5.000000. No vessel got worse and the band stopped admitting any of them.'),
  ('separation', 'advanced', 'module', 'm03-the-family-of-vessels', 10, 'verticalUnsortedListSmallestFeasible has its 7.000000 ft and 8.000000 ft rows both feasible and both inside a band of 1.000000 to 2.000000. The repaired sweep prefers 7.000000 ft and the retired rule preferred 8.000000 ft. What produced the retired answer?', '["The position of 8.000000 ft in the array it was handed, because the retired rule took the first row it met inside the band and the diameters had not been supplied in order.", "Its slenderness of 1.040882 sits closer to the middle of the band of 1.000000 to 2.000000 than the 1.291345 of the 7.000000 ft row, and the retired rule broke ties on that distance.", "Its gas margin is the wider of the two feasible rows, and the retired rule broke a tie between qualifying vessels on the margin each one carried rather than on the diameter.", "Its length of 8.327054 ft is the shorter of the two, and the retired rule preferred the shorter vessel."]'::jsonb, 0, 'A recommendation that depends on the order somebody typed the diameters is not a recommendation about vessels. The repaired rule takes 7.000000 ft because it is the smaller.'),
  ('separation', 'advanced', 'module', 'm03-the-family-of-vessels', 11, 'On horizontal2InBandButGasOverloaded the 7.500000 ft row has a slenderness of 4.706969 and a length of 35.302269 ft with inRange true, and the sweep prefers 8.500000 ft. What is wrong with the 7.500000 ft vessel?', '["Its length of 35.302269 ft exceeds what the sweep will recommend, so the answer moves up to the 27.484466 ft of the 8.500000 ft row on length grounds.", "Its slenderness of 4.706969 sits above the middle of the band of 3.000000 to 5.000000, and the sweep prefers the row nearest the centre of the band it was given.", "It is infeasible with reasons gas-capacity, so a well proportioned drum cannot carry the gas it was given.", "It carries water-carryover, which is the reason that gates feasibility on a horizontal family and the reason the retired rule was unable to see when it recommended it."]'::jsonb, 2, 'The retired rule recommended it because it was the first in-band row. The repaired sweep passes over it to 8.500000 ft, slenderness 3.233467, length 27.484466 ft, reasons none.'),
  ('separation', 'advanced', 'module', 'm03-the-family-of-vessels', 12, 'd1ProbeVertical4ftGasOverloaded returns preferred null with status none-in-band. Why is it not none-feasible?', '["Because its 4.000000 ft row is inside the band of 3.000000 to 5.000000, and a status of none-feasible is only returned where no row is inside the band either.", "Because none-feasible is reserved for families whose rows fail on water carryover, and every failing row on this case fails on gas capacity instead.", "Because the sweep found a feasible row inside the band and then rejected it on size, which is the situation the none-in-band status was added to report.", "Its 7.000000 ft and 8.000000 ft rows are feasible and out of band."]'::jsonb, 3, 'The 4.000000 ft row is inRange true and feasible false on gas capacity, while the 7.000000 ft and 8.000000 ft rows are feasible with ld-out-of-band. Feasible vessels exist, so the band is the thing to revisit.'),
  ('separation', 'advanced', 'module', 'm03-the-family-of-vessels', 13, 'A sweep returns none-feasible and an engineer widens the band to bring more rows in. What will that achieve?', '["It will recover the rows that were excluded for slenderness, which on verticalNoneFeasible brings the 2.000000 ft row at 21.616431 back into range and makes it the preference.", "Nothing at all, because shape alone was never what kept a row out there, and a band touches inRange and the reason list and reaches no further than that.", "It will return a preferred diameter once at least one row is in band, since a status of none-feasible is a statement about the band rather than about the vessels.", "It will move the status to none-in-band, which is the status a family reports once its band admits rows that do not work."]'::jsonb, 1, 'verticalNoneFeasible carries a band of 1.000000 to 10.000000 already, and its 3.000000 ft and 4.000000 ft rows are inRange true and infeasible on gas capacity. Widening changes neither flag.'),
  ('separation', 'advanced', 'module', 'm03-the-family-of-vessels', 14, 'A report quotes a preferred diameter of 7.000000 ft for ABANA-2 and nothing else. What has the reader not been given?', '["The band it was asked in, along with the row behind it: a length of 30.394173 ft, a slenderness of 4.342025, two flags and a reason list, and the status word that says a vessel was actually selected.", "The diameters that were swept, which is the only missing input, since the preference is a property of the vessel once the list is known.", "The gas margin on the row, which the sweep prints beside every diameter it reports on.", "The droplet specification, which matters on three-phase families and not on a two-phase one such as ABANA-2."]'::jsonb, 0, '7.000000 ft in a band of 3.000000 to 5.000000 and a null in a band of 4.000000 to 5.000000 are two honest answers about one family, so a preference quoted without its band has left out half the question.'),
  ('separation', 'advanced', 'module', 'm03-the-family-of-vessels', 15, 'The ABANA-2 rows at 5.000000 ft and 6.000000 ft both carry two reasons. What does that tell a reader about which of them is worse?', '["The 5.000000 ft row is the worse of the two, because its slenderness of 11.914516 is further outside the band than the 6.894974 of the 6.000000 ft row.", "The 6.000000 ft row is the worse of the two, because it is nearer the band and so it is the row a reader is most likely to accept without checking it.", "Nothing: the reason list is a set of objections in no order, and what separates those two rows is a gas margin the list does not print.", "They are equally bad, since two reasons on a row of a sweep is the worst score a row can be given and both of them carry it."]'::jsonb, 2, 'Reasons are not a severity ranking. Both rows are infeasible on gas capacity and both are out of band, and the 5.000000 ft row needs 59.572579 ft of length against the 41.369847 ft of the 6.000000 ft row.'),
  ('separation', 'advanced', 'module', 'm04-judging-a-layout', 1, 'What has to be true of a pair of items before the layout check counts it as a check?', '["Both items are placed with usable coordinates and the requirement between them is positive, so a comparison can be made and can fail.", "Both items are placed and the table carries an entry for the pair, whether that entry is a positive distance or the 0.000000 m it records for a valve beside a relief valve.", "One of the two carries a computed setback, since a table figure is recorded rather than calculated and cannot by itself produce a check on a plan.", "Both items are of a type the spacing table knows, which is what the unknown pair count of 12 on ERHA is recording."]'::jsonb, 0, 'ERHA reports 69 checks against 21 zero-requirement pairs, 2 skipped items and 12 unknown type pairs. Only the first of those four numbers is a comparison that was made.'),
  ('separation', 'advanced', 'module', 'm04-judging-a-layout', 2, 'A separator beside a valve requires 0.000000 m, and the engine counts that pair separately rather than as a check. Why?', '["Because the table figure of 0.000000 m is a null in disguise and the lookup is symmetric, so the pair is recorded in the unknown list instead of among the checks.", "Because the two items are so close together that the haversine distance between them falls below the resolution the engine will report at site scale.", "A comparison against zero can never fail, so counting it would pad the review with results that were settled before any distance was measured.", "Because a zero requirement belongs to the computed half of the check rather than the table half."]'::jsonb, 2, 'ERHA carries 21 such pairs beside its 69 checks. The published case s3ZeroRequirementPairOnly reports checked 0 with zeroRequirementPairs 1, where the retired rule reported checked 1 and passed on it.'),
  ('separation', 'advanced', 'module', 'm04-judging-a-layout', 3, 'ERHA reports checked 69, zeroRequirementPairs 21, skipped 2 and unknownPairs 12. What are the last three of those counts for?', '["They are the three categories of breach the check found, ranked from the least serious to the most serious as the engine walked the plan.", "They are the three things that were not comparisons, reported apart from the checks so that a reader can tell a quiet plot from an unexamined one.", "They are the pairs that cleared their requirement, which is why they are kept out of the count of 69 comparisons that were made.", "They are counts of items rather than of pairs, so each one says how many pieces of equipment on the plan fall into that category."]'::jsonb, 1, 'Complete is false on ERHA because of the 2 skipped items and the 12 unknown pairs. A pair the table scores at zero takes nothing away from coverage: s3ZeroRequirementPairOnly reports zeroRequirementPairs 1 with complete true.'),
  ('separation', 'advanced', 'module', 'm04-judging-a-layout', 4, 'ERHA skips tk2 with reason bad-coordinates and fl2 with reason radiation-source-not-placed. What does each reason mean for the plan?', '["One item sits outside the plot boundary the datum defines, and one is a source whose allowable radiation level was left blank on the input form.", "One item has coordinates the engine read as a string rather than a number, and one is a duplicate of a source already on the plan and is dropped to avoid double counting.", "One item failed its own comparison and was withdrawn from the count, and one produced a setback the engine could not compare because nothing was placed near it.", "One item could not be located at all, and one radiation source is missing, so the setback it would have produced was never computed."]'::jsonb, 3, 'Both are absences with names attached, which is what makes them actionable. radiationAndTableWithGhostSource skips a source called ghost and still reports checked 2 with 2 violations.'),
  ('separation', 'advanced', 'module', 'm04-judging-a-layout', 5, 'A tank beside a chemical injection skid returns null from the spacing table. What is the engine saying, and what would defaulting it to zero do?', '["It is saying the table has no entry, and a zero would turn that silence into a positive statement that no separation is required between them.", "It is saying the two items may be placed together, and a zero would record the same thing in a form the layout check can compare a distance against.", "It is saying the pair needs a computed setback rather than a table figure, and a zero would send it down the table path instead.", "It is saying the skid was skipped, and a zero would put it back into the count of checks where a reviewer could see it."]'::jsonb, 0, 'ERHA reports 12 unknown type pairs from one skid, and a flow meter, a pig launcher or a booster package returns null in the same way. The lookup is symmetric, so null comes back in both directions.'),
  ('separation', 'advanced', 'module', 'm04-judging-a-layout', 6, 'Which published case is complete and failing, and which is passing and incomplete?', '["s3ZeroRequirementPairOnly is complete and failing on its single zero-requirement pair, and unknownPairIncomplete is passing while two type pairs stayed unknown.", "radiationAndTableWithGhostSource is complete and failing on 2 violations, and s3AllUnplacedNothingChecked is passing while both of its items went unplaced.", "s4RankingsDisagree is complete with pass false on 2 violations, and s3SkippedItemPassesButIncomplete is pass true with complete false on one skipped item.", "unknownPairIncomplete is complete and failing on its 1 violation, and s4RankingsDisagree is passing on all 6 of the comparisons it made."]'::jsonb, 2, 'Complete is a statement about coverage and pass is a statement about results. Those two cases are the whole lesson, because each has one field true and the other false.'),
  ('separation', 'advanced', 'module', 'm04-judging-a-layout', 7, 'ERHA reports complete false and pass false. What are the two separate causes?', '["Pass is false because 21 pairs carried no requirement and could not clear, and complete is false because only 69 of the pairs on the plan were reached at all before the run ended.", "Pass is false because 6 comparisons came up short, and complete is false because 2 items were skipped and 12 type pairs are unknown.", "Both are false for the same reason, the 2 skipped items.", "Pass is false on the flare setback of 64.6458 m, and complete on the bund radius."]'::jsonb, 1, 'The two fields answer different questions and move independently. Complete would still be false on ERHA if all 69 comparisons had cleared, because the remainder is what complete is about.'),
  ('separation', 'advanced', 'module', 'm04-judging-a-layout', 8, 's3AllUnplacedNothingChecked and s3ZeroRequirementPairOnly both report pass null with passStatus nothing-checked. Why does complete differ between them?', '["One was judged against the table and the other against a computed setback, and only a table comparison can leave a layout complete when nothing was checked on it.", "One reports zeroRequirementPairs 1 and a zero-requirement pair counts toward coverage, while a skipped item is counted against it and also against the pass field.", "One has two items and the other has one pair, and complete is set from the number of items a plan carries rather than from what stopped the comparisons.", "One had two items it could not reach, and the other had nothing stopping the judgement at all."]'::jsonb, 3, 's3AllUnplacedNothingChecked skips w1 and s1 for bad coordinates and reports complete false. s3ZeroRequirementPairOnly skips nothing and reports complete true with checked 0.'),
  ('separation', 'advanced', 'module', 'm04-judging-a-layout', 9, 'A layout check reports pass null. Why is null the honest answer where true is not?', '["Pass is a claim about the comparisons that were made, and with no comparisons there is no set to quantify over, so the question does not apply rather than being answered yes.", "Because null is how the engine reports a plan it refused, and a plan with nothing to check is refused in the same way as a value that is not a list.", "Because true is reserved for a plan that is also complete, and a plan with nothing checked can never be complete.", "Because a boolean cannot carry a count, and pass has to hold both the verdict and the number of comparisons behind it."]'::jsonb, 0, 'The retired rule reported pass true on both nothing-checked cases, which is an absence of violations read as a presence of compliance. A plan whose items lost their coordinates in an import came back green.'),
  ('separation', 'advanced', 'module', 'm04-judging-a-layout', 10, 'On ERHA worstAbsolute names Flare stack to Control room and worstRelative names Transfer pump A to Transfer pump B. What figure is each ranking built on?', '["46.1777 m of measured distance for the flare pair, and 1.2067 m of measured distance for the pump pair, so both rankings sort on the distance that was measured.", "90.0000 m of requirement for the flare pair, and 3.0000 m of requirement for the pump pair, so the rankings sort by how demanding each requirement is.", "43.8223 m of shortfall for the flare pair, and 0.597753 of its own requirement for the pump pair.", "0.486914 of the requirement for the flare pair, and 1.7933 m of shortfall for the pump pair, which is why the two rankings name different pairs on this plan."]'::jsonb, 2, 'The pump pair is last on metres and first on fraction, and the flare pair is the other way round. Both namings are correct and neither is called the worst on its own.'),
  ('separation', 'advanced', 'module', 'm04-judging-a-layout', 11, 'Why does a works order written from the relative ranking alone go wrong on ERHA?', '["It starts with the control room, because a fraction of 0.486914 outranks a fraction of 0.597753 whenever the requirement behind it is the larger of the two.", "It starts with two pumps 1.7933 m apart from their requirement and buries the control room that is 43.8223 m short of its own.", "It treats the 6 breaches as one list when 4 of them are radiation breaches against a computed setback and 2 are spacing breaches against a table figure.", "It leaves out the 2 skipped items, which carry no shortfall at all."]'::jsonb, 1, 'A fraction has no size in it. The pump pair is a chalk line and a day of steelwork; the flare pair is a different building or a different plot.'),
  ('separation', 'advanced', 'module', 'm04-judging-a-layout', 12, 'On radiationAndTableWithGhostSource and on unknownPairIncomplete the two rankings name the same pair. What does that show?', '["That the two rankings are the same calculation reported twice, and they separate only where a plan carries both a table breach and a radiation breach on it.", "That a plan with fewer than three breaches cannot separate the two rankings, since a ranking needs at least three entries before an ordering can differ.", "That agreement is the normal case and ERHA disagrees only because its pump pair carries the smallest requirement the spacing table holds at 3.0000 m.", "That the two orderings often agree, which is how a single ranking survived as long as it did."]'::jsonb, 3, 'radiationAndTableWithGhostSource names f1 to t1 on both, 18.1988 m of 68.1427 m and 0.267069. s4RankingsDisagree is the case built to separate them, at 40.0561 m of 90.0000 m against 0.667041.'),
  ('separation', 'advanced', 'module', 'm04-judging-a-layout', 13, 'The retired code returned one ranking built on the relative shortfall and labelled it worst, reporting spacing p1 to p2 on s4RankingsDisagree. Which part of that is the defect?', '["The label, because calling one of two orderings the worst hides the other one, where naming it the largest relative shortfall would have been true and would have invited the question about metres.", "The ranking, because a relative shortfall is the wrong quantity to sort breaches by and an absolute shortfall in metres is the right one.", "The pair, because spacing p1 to p2 is not a breach on that case at all and the retired code was reading a zero-requirement pair as a violation.", "The count, because the retired code reported checked 6 where the repaired engine counts only the comparisons that carried a positive requirement."]'::jsonb, 0, 'The retired pair is the one whose absolute shortfall is the smaller. worstAbsolute on that case is spacing f1 to c1, 40.0561 m of 90.0000 m, and worstRelative is p1 to p2 at 0.667041.'),
  ('separation', 'advanced', 'module', 'm04-judging-a-layout', 14, 'A reviewer proposes combining the two rankings into a single score so that one list can be escalated. What is wrong with that?', '["Nothing is wrong with it, provided both are normalised against the largest requirement on the plan, which on ERHA is the 90.0000 m between a flare and a control room.", "A shortfall in metres and a shortfall as a fraction are different quantities, so a combined index hides which of the two put a pair at the top of it.", "The engine already returns such a score and the two rankings are the inputs to it, so a reviewer would be rebuilding a field that is printed.", "The two rankings cover different sets of breaches, since worstAbsolute is drawn from spacing pairs and worstRelative from radiation pairs."]'::jsonb, 1, 'On ERHA the pump pair leads on 0.597753 and the flare pair leads on 43.8223 m. A single number would rank them and would not say which quantity did the ranking.'),
  ('separation', 'advanced', 'module', 'm04-judging-a-layout', 15, 'A plan reports 69 checks. What does that number depend on besides how thorough the review was?', '["The order the items were supplied in, since the engine walks the list in that order and stops counting once it reaches the first pair it cannot resolve from the spacing table.", "The number of computed setbacks, because each radiation source multiplies the count by the number of items placed near it on the plan.", "What happens to be on the plan: adding items adds pairs, and a plot with many zero-scored items can show a large count with nothing more examined.", "The datum the coordinates were measured from, because a distance on a sphere is measured from the datum and the count follows the distances."]'::jsonb, 2, 'ERHA reports 21 zero-requirement pairs beside its 69 checks, and the separate count is what makes the shape of the number visible to a reader.'),
  ('separation', 'advanced', 'module', 'm05-what-the-method-does-not-know', 1, 'The K derating and its floor are held for the literature. What may a design report take from them, and what may it not?', '["It may quote the derated K of 0.300000 at 600.000000 psig as a design basis, and it may not quote the floor of 0.120000, which is the only half of the rule that is unchecked.", "It may use any derated K below the floor of 0.120000, and it may not use one above it, since the floor marks where the rule of thumb was checked against a source.", "It may state the published table values and the fact that the engine derates, and it may not lean on a derated figure as though it were calculated.", "It may quote the rule where a vessel is vertical, and it may not where a vessel is horizontal, because only the vertical rows of the table carry a checked derating."]'::jsonb, 2, 'What is unchecked is the published form: whether the slope is 0.01 per 100 psi, whether it starts at 100 psig, and whether any source puts a floor there at all. A conclusion built on a derated K carries the uncertainty of the rule.'),
  ('separation', 'advanced', 'module', 'm05-what-the-method-does-not-know', 2, 'verticalNoneAt650psig returns K 0.125000 with derated true, floored false and nearFloor true, against the floor of 0.120000. What is nearFloor reporting?', '["That the floor did not catch this K, and that one more 100 psi step of the same rule would put it under, so the value sits 0.005000 from the edge of the range where the rule of thumb stops meaning anything.", "That the engine has replaced the value the rule produced, since a K landing within one step of 0.120000 is reported at the floor rather than at the figure the derating actually gave for that row.", "That a warning has been raised on this row, which is the engine asking for a vendor K wherever the derating comes close enough to the floor that the rule behind it stops meaning anything.", "That the derating rule ran twice on this row, which is how a bare drum starting from 0.180000 falls to within half a step of the floor at an operating pressure as modest as this one."]'::jsonb, 0, 'nearFloor is true when the floor did not catch the value and one more 100 psi step of the rule would. It is a flag and not a warning: the return on that row still carries a null warning, and floored and nearFloor are never true together.'),
  ('separation', 'advanced', 'module', 'm05-what-the-method-does-not-know', 3, 'At 3000.000000 psig the derating gives -0.110000 and the engine returns 0.120000 with floored true. How should that number be read?', '["As the lowest K any mist extractor can produce, measured across the six published rows of the table and rounded to the nearest hundredth for reporting.", "As the engine declining to extrapolate, so the K it returned was chosen rather than computed, and a vendor K is the only honest input at that pressure.", "As a conservative K, since holding the value up at 0.120000 rather than letting it fall gives a smaller settling velocity and a larger vessel.", "As the derated value with its sign corrected, because a negative settling coefficient is an arithmetic artefact of the rule rather than a statement about the vessel."]'::jsonb, 1, 'A linear rule extrapolated far enough produces a negative number, which is the clearest signal that it is being used outside the range anybody intended. The floor is a guard rail and 0.120000 has no derivation behind it here.'),
  ('separation', 'advanced', 'module', 'm05-what-the-method-does-not-know', 4, 'A vendor supplies K as an override and the engine returns source typed with derated false and floored false. What does the engine do about the table value at that pressure?', '["It records the table value beside the override so a reviewer can see both, which is what the derated and floored flags are reporting as false on that row.", "It refuses an override that sits more than one derating step away from the table value at that pressure, which is the guard that keeps a typed K honest.", "It applies the pressure derating to the override as well, so a typed K of 0.28 falls by 0.01 per 100 psi above 100 psig in the same way a table value does.", "Nothing at all: it never compares the two and raises no warning when they are far apart."]'::jsonb, 3, 'An override wins outright and says so. A vendor K of 0.9 would be taken silently, which is why an override belongs in a report beside the pressure it was quoted for.'),
  ('separation', 'advanced', 'module', 'm05-what-the-method-does-not-know', 5, 'A horizontal vessel needs a droplet settling velocity for its gas length. What does this engine use, and why is that held?', '["It uses the Souders-Brown velocity at the horizontal K, which was written to say what velocity a gas may carry without lifting liquid out, and that packaging has not been read against a published method.", "It uses the Stokes velocity of the smallest droplet in the specification, which is held because the field constant 1.78e-6 sits four parts in a thousand below the SI derivation on every one of the three published Stokes cases.", "It uses the gas velocity in the gas space, which is held because the gas area depends on a liquid level somebody typed in rather than measured.", "It uses a settling velocity measured on the published cases, which is held because all of those cases are synthetic rather than measured on a separator."]'::jsonb, 0, 'The two quantities are related and they are not the same. Until the published method is read, the gas length and everything drawn from it are held.'),
  ('separation', 'advanced', 'module', 'm05-what-the-method-does-not-know', 6, 'The engine gate pins that the gas length can never exceed the gas height. What follows from that, and what would have to be re-read if the literature moves the packaging?', '["That a horizontal vessel is always liquid controlled, and only the published cases would have to be re-run if the packaging moved, since the engine gate pinning the ratio at 1 would still hold whatever the literature says.", "That the gas margin can never fall below 1, and the margin table across the ABANA-2 family would have to be recomputed if the settling velocity were defined from a droplet diameter instead of from the Souders-Brown packaging.", "Gas can control only a vessel that is gas overloaded or shorter than its own diameter; the gas length, that claim and that observation would all have to be re-read together.", "That the gas length is always shorter than the liquid length, and the controlling field would have to be re-read while the two lengths themselves would stand."]'::jsonb, 2, 'The gas length is the velocity ratio times the gas height, and the capacity rule caps that ratio at 1. Every published case where gas controls is a case where gasCapacityOk is false.'),
  ('separation', 'advanced', 'module', 'm05-what-the-method-does-not-know', 7, 'gasOverloaded6ftGasControls runs a gas velocity of 2.829421 ft/s against a settling velocity of 0.500000 ft/s. What is the honest reading of that vessel today?', '["That its gas length of 16.976527 ft is the design length for the duty, since the gas requirement is the larger of the two lengths on that row and the engine reports it as the controlling requirement.", "That it is gas overloaded, with a margin of 0.176715 and gasCapacityOk false, which is a result from the capacity comparison rather than from the borrowed packaging.", "That its settling velocity of 0.500000 ft/s is too low to be trusted, because a figure that round is a placeholder rather than a Souders-Brown velocity computed at the horizontal K of the mist extractor.", "That the vessel is too short, since a gas length of 16.976527 ft against a gas height of 3.000000 ft is the ratio the capacity rule caps at 1."]'::jsonb, 1, 'The margin is a real result. The gas length of 16.976527 ft depends on the held packaging, so a conclusion drawn from it carries that premise with it.'),
  ('separation', 'advanced', 'module', 'm05-what-the-method-does-not-know', 8, 'A layout report quotes 90.0000 m between a flare and a control room and 64.6458 m of flare setback. What separates those two figures?', '["One is measured on the site at the datum of the plan and one is computed from the duty, so the first moves whenever the survey is redone and the second stays where it is.", "One is a radiation figure and one is a spacing figure, and the layout check compares the two kinds against different distances, centre to centre against edge to edge.", "One is held for the literature and one is not, since the API 521 allowable of 4.730000 kW/m2 that produced 64.6458 m is a checked publication with a source behind it.", "One is a table value somebody recorded and one is computed from 828000.0000 kW of heat release."]'::jsonb, 3, 'Change the relief rate, the heating value or the allowable and the setback moves. Change nothing and 90.0000 m stays 90.0000 m, because it was never a function of anything.'),
  ('separation', 'advanced', 'module', 'm05-what-the-method-does-not-know', 9, 'The engine carries four API 521 radiation levels with words attached, from 1.580000 kW/m2 for continuous exposure up to 9.460000 kW/m2 for seconds only on an escape route. How should those labels be used?', '["As recorded values with no source checked, so the allowable chosen for a calculation is an input somebody has to stand behind and the wording beside it is a convenience.", "As the four allowables the engine will accept, since a setback computed at any other level is refused with a message naming the allowable input as one that has to be picked from the published set.", "As checked publication values, which is why the flare setback of 64.6458 m computed at 4.730000 kW/m2 can be quoted without qualification.", "As a ranking of severity, so the level chosen follows from how long people are expected to stay rather than from any site standard."]'::jsonb, 0, 'The levels and their wordings are recorded rather than verified. The computed half of a setback moves with its duty, and the level it was computed against is a decision.'),
  ('separation', 'advanced', 'module', 'm05-what-the-method-does-not-know', 10, 'The spacing table returns null for a tank beside a skid. What is the right handling, and what is the temptation?', '["Substitute the nearest comparable pair from the table, such as the 15.000000 m recorded between a separator and a tank, and note the substitution in the report.", "Treat the pair as skipped, since an item the table cannot score is an item the layout check could not reach and belongs in the skipped list with a reason.", "Carry it as an unknown pair and put the question to whoever owns the site standard; the temptation is a zero, which claims no separation is required.", "Compute a setback for it from the duty of the nearer item, which is what the engine does for a flare or a pool fire when no table figure exists."]'::jsonb, 2, 'The table is recorded with no source checked and is meant to be replaced by a site standard wholesale. A pair it does not carry is a question for that standard rather than a gap to fill in.'),
  ('separation', 'advanced', 'module', 'm05-what-the-method-does-not-know', 11, 'Every published case in this course is synthetic. What can that kind of golden prove?', '["That the engine reproduces measured separator performance within the tolerance each case carries, since the oracle was written from the same physics in SI units where the engine works in field units, which is the cross-check the golden set was built to make.", "That two implementations written by different people in different unit systems agree on the arithmetic, which catches a slip or a dropped conversion and cannot catch a method that is wrong in both files.", "That the engine is correct wherever the two agree and in doubt wherever they do not, which is why the Stokes ratio of 1.004184 is recorded as an open question.", "That the published cases cover the domain, since an oracle can be run at any conditions and the cases were chosen to span the range the engine is used in."]'::jsonb, 1, 'If the physics being encoded is the wrong physics, the oracle agrees with the engine and both are confidently wrong together. Agreement between two implementations is evidence about arithmetic.'),
  ('separation', 'advanced', 'module', 'm05-what-the-method-does-not-know', 12, 'The four distance cases agree exactly across haversine, Vincenty and the chord, at 89.4099 m, 489.2584 m, 55.5975 m and 1111.9508 m. What does that establish?', '["That the earth radius the engine uses is the right one for a site plan, since three separate methods built on it return the same figure at four different latitudes.", "That a site plan can be treated as a flat grid at these distances, which is why the chord and the two surface methods land on the same answer to four decimals.", "That the layout check will not produce a false breach, because the distances behind its 69 comparisons are exact to the precision the engine prints them at.", "That the distance arithmetic is sound at site scale, and nothing at all about whether the coordinates match the steel."]'::jsonb, 3, 'Three methods agreeing to the printed figure is evidence about the arithmetic. A coordinate that was typed from a drawing rather than surveyed is a different question and no golden here touches it.'),
  ('separation', 'advanced', 'module', 'm05-what-the-method-does-not-know', 13, 'The Stokes oracle sits at 1.004184 times the engine on all three published cases. Why is that kept and stated rather than repaired?', '["The field form with its constant of 1.78e-6 is what the standards and the vendor datasheets are written in, so the course keeps the form and carries the size of the gap, four parts in a thousand and always low.", "Because the oracle is the approximation, since an SI derivation of g d2 dRho over 18 mu ignores the shape factor that the field constant absorbs.", "Because the gap is smaller than the tolerance any golden carries, so repairing it would move no published expectation.", "Because the two forms disagree only at large droplet sizes, where 0.320400 ft/s meets 0.321740 ft/s, and no verdict in the course is decided there."]'::jsonb, 0, 'This is a stated convention with its size named rather than a held item. Any gate on droplet settling holds a tolerance wider than that, because a case cut fine enough could turn a verdict on the constant alone.'),
  ('separation', 'advanced', 'module', 'm05-what-the-method-does-not-know', 14, 'The DAK z factor refuses a gas at Tpr 0.848 and accepts one at Ppr 0.149 with a note. Why are the two treated differently?', '["A refusal is reserved for a reduced temperature and a note for a reduced pressure, because the fit is a function of pressure alone once the temperature is inside its band.", "The cold case would have produced a negative z and the low-pressure case would not, so only one of the two could be returned as a number at all.", "Outside the validity range of 1.000000 to 3.000000 in Tpr the answer would be an extrapolation and is refused; below the fit data at Ppr 0.200000 the surface runs to the ideal gas limit, which is where an ordinary low-pressure separator sits.", "The low-pressure case was accepted because a note is cheaper than a refusal on a common condition, and the cold case is rare enough to refuse outright."]'::jsonb, 2, 'The accepted case returns z 0.986286 and a density of 0.317797 lb/ft3 with its note. A refusal is a golden too, because it records where the method stops.'),
  ('separation', 'advanced', 'module', 'm05-what-the-method-does-not-know', 15, 'A reviewer dismisses the whole golden set because every case is synthetic. What has that argument missed?', '["That the goldens are measured wherever a case carries a note, since a note records an observation from a separator rather than a figure from the oracle that re-derives the same physics in SI units.", "Those cases caught real defects in this engine, and the constant Stokes ratio of 1.004184 is a finding that appeared only because two implementations were run side by side.", "That a synthetic case can be run at conditions no separator has ever been operated at, which makes it stronger evidence than a measurement would be.", "That the distance cases are not synthetic, since haversine and Vincenty are published methods and their agreement at 89.4099 m is an external check."]'::jsonb, 1, 'The mistake runs both ways. Reading a green suite as agreement with measured separator performance upgrades the claim, and dismissing the suite throws away the arithmetic evidence it does carry.'),
  ('separation', 'advanced', 'module', 'm06-the-expert-reading', 1, 'The AGBAMI chain runs gauge pressure, reduced pair, z, gas density, K, settling velocity, then the vessel. Why can the steps not be taken in another order?', '["They can be taken in any order provided every figure is recomputed at the end, which is what the studio does when a user edits a field halfway down the chain.", "Each step is an input to the next one: the reduced pair needs the absolute pressure, z needs the reduced pair, the density needs z, settling needs K and the densities, and the vessel needs settling.", "K has to be taken first, because the mist extractor decides which orientation the rest of the chain is worked in.", "The vessel has to be sized first, because the residence times the verdicts need come from a length."]'::jsonb, 1, 'On AGBAMI the chain runs 350.000000 psig to Ppr 0.549797 and Tpr 1.508700, z 0.947166, a density of 1.276898 lb/ft3, K 0.525000, settling 3.549130 ft/s and 8.713371 ft3/s of gas.'),
  ('separation', 'advanced', 'module', 'm06-the-expert-reading', 2, 'AGBAMI runs at 350.000000 psig and 110.000000 degF behind a vane pack. What does the chain report for z and for K?', '["z 0.908065 and K 0.300000, which are the figures the same vane pack produces once the pressure is taken as absolute rather than as gauge.", "z 0.947166 and K 0.550000, since the vane pack carries a base K of 0.550000 and the derating rule starts above the pressure this vessel runs at.", "z 0.850000 and K 0.525000, because a three-phase vessel takes the retired constant for z and derates only the K that the mist extractor supplies.", "z 0.947166 and K 0.525000."]'::jsonb, 3, 'The reduced pair 0.549797 and 1.508700 gives z 0.947166, and the horizontal vane pack base of 0.550000 derates to 0.525000 at 350.000000 psig. Both figures move every dimension below them.'),
  ('separation', 'advanced', 'module', 'm06-the-expert-reading', 3, 'AGBAMI is 10.000000 ft across at a level of 0.500000 and needs 12.311666 ft of length, with the controlling requirement liquid-retention. What would a reader have to add before that length could be acted on?', '["The interface at 3.049149 ft with the layers it implies, the droplet specification the verdicts were taken at, and the word liquid-retention itself, since a gas-controlled row is a different finding.", "The slenderness of the drum, which is the only figure a fabricator needs beyond the diameter and the length the engine returned.", "The gas rate of 8.713371 ft3/s, because the length is divided between the two phases in proportion to it.", "The band the sweep was run in, because a length is only meaningful once it has been judged against a slenderness band."]'::jsonb, 0, 'A length with no interface, no specification and no controlling requirement beside it is a number. The same drum returns 12.311666 ft whether the water verdict passes or fails.'),
  ('separation', 'advanced', 'module', 'm06-the-expert-reading', 4, 'Both AGBAMI droplet verdicts pass at 500.000000 micron and the water verdict fails at 150.000000 micron. What does a design package have to carry for either statement to mean anything?', '["The oracle velocities beside the engine velocities, because the field form sits 1.004184 below the SI derivation and a verdict quoted without that gap overstates its own precision.", "The vessel length of 12.311666 ft and the liquid level of 0.500000, which are the two inputs that decide a verdict once the stream has been fixed.", "The droplet size each verdict was taken at, because a verdict without its specification is a conclusion with its premise removed.", "The retention times of 5.000000 minutes and 8.000000 minutes, since a verdict is a comparison against a residence and the residence is the retention time typed in."]'::jsonb, 2, 'The same drum gives waterCarryover false at 500.000000 micron and true at 150.000000 micron. Nothing about the vessel moved between those two runs.'),
  ('separation', 'advanced', 'module', 'm06-the-expert-reading', 5, 'ERHA needs 64.6458 m of flare setback and its bund gives 59.5294 m from the pool centre with 50.5294 m from the pool edge. What is the site report, in one reading?', '["6 breaches on a complete plan, since every item on the station was reached and the two computed setbacks were both compared against the distances measured.", "6 breaches on a plan that is not complete, the largest 43.8223 m and the sharpest 0.597753 of its requirement, with 2 items skipped.", "2 breaches against the computed setbacks and 4 against the table, which is the split the two rankings are drawn from separately.", "No breaches, because the largest shortfall of 43.8223 m is measured against a table figure of 90.0000 m that the site standard may replace."]'::jsonb, 1, 'Complete is false because 2 items were skipped and 12 type pairs are unknown, and pass is false because 6 comparisons came up short. The two fields have separate causes.'),
  ('separation', 'advanced', 'module', 'm06-the-expert-reading', 6, 'Which of these answers from an Expert run is a status word rather than a number?', '["The controlling requirement on a three-phase row, which reads as a length in ft once the larger of liquid retention and gas capacity has been taken.", "The margin in a gas capacity check, which reads as a ratio and is the figure a reader compares against the verdict that was printed beside it.", "The water share of the liquid cross-section, which reads as a fraction such as 0.516129 and decides where the interface is placed in the drum.", "preferredStatus, which reads selected, none-feasible or none-in-band."]'::jsonb, 3, 'This tier introduced four answers that are not numbers: retentionPhase, preferredStatus, pass with its nothing-checked status, and complete beside pass. Each is a case a retired rule answered with a number it had not earned.'),
  ('separation', 'advanced', 'module', 'm06-the-expert-reading', 7, 'This engine sizes a vessel. Which two questions does it leave to other work, and where does each belong?', '["What actually leaves each stage at a given pressure and temperature, which is a flash calculation in the fluid engine, and the slug volume, which comes from the line where the pigging work produces it.", "The droplet verdicts, which belong to the laboratory that measured the crude, and the spacing table, which belongs to whoever owns the site standard.", "The z factor, which belongs to the gas properties module, and the radiation labels, which belong to API 521 and are quoted rather than computed.", "The slenderness band, which is a plot decision, and the retention times, which come from the process engineers rather than from this engine."]'::jsonb, 0, 'A sizing result says the drum is big enough for the stream to separate in it. It never says what the compositions at the outlets will be, and it never computes the slug it is asked to hold.'),
  ('separation', 'advanced', 'module', 'm06-the-expert-reading', 8, 'A team has results from before FC1-0. Which of them has to be run again, and why?', '["Only the results that failed, since a failing case is the one where a repaired rule could move the answer and a passing case was never in any doubt at the time the package was signed off by the reviewer.", "Only the three-phase results, because the two-phase path was untouched by FC1-0 and its lengths and margins still stand as reported.", "Every carryunder verdict, every preferred diameter and every layout that passed with nothing checked, because each answered a different question from the one it appeared to answer.", "None of them, provided the inputs were recorded, since the repairs changed how answers are reported rather than what the arithmetic produced."]'::jsonb, 2, 'A carryunder judged against a chord-rule layer was judged on a vessel whose water band was never that thin, a retired preference could be a row that was merely first, and a pass on nothing checked was an absence of evidence.'),
  ('separation', 'advanced', 'module', 'm06-the-expert-reading', 9, 'What question separates the parts of a design package that survive a review from the parts that do not?', '["Whether each figure carries six decimals, since vessel work printed to fewer decimals has been rounded somewhere between the engine and the report, which is the one check a reviewer can make without re-running anything.", "Whether each figure was computed, copied or refused, because a computed figure moves when its duty moves, a copied figure never moves, and a refusal names the input it wants.", "Whether each figure came from the repaired engine, since anything from before FC1-0 is unreliable and anything after it is not.", "Whether each figure has a published case behind it, since a figure with a golden is checked and a figure without one is an assertion."]'::jsonb, 1, 'The ERHA flare setback of 64.6458 m moves with 828000.0000 kW of heat release. The 90.0000 m between a flare and a control room does not move at all, because it was never a function of anything.'),
  ('separation', 'advanced', 'module', 'm06-the-expert-reading', 10, 'Why does this tier insist that a sized vessel and a judged plot are two halves of one answer?', '["Because a drum that separates the stream is useless on a plot that cannot hold it, and a plot judged clear says nothing about whether the vessel on it works.", "Because the layout check reads the vessel dimensions, so a diameter of 10.000000 ft changes the distances between the items on the plan once the drum has been placed on it.", "Because the flare setback of 64.6458 m is computed from the gas the separator releases, so the two calculations share the same duty and the same allowable of 4.730000 kW/m2.", "Because the spacing table scores a separator against a tank at 15.000000 m, which is the figure that sizes the plot the drum stands on."]'::jsonb, 0, 'AGBAMI answers with a vessel of 12.311666 ft and a verdict at each droplet size. ERHA answers with 6 breaches, 2 skipped items and two rankings. Neither answer contains the other.'),
  ('separation', 'advanced', 'module', 'm06-the-expert-reading', 11, 'One three-phase family, swept twice at two droplet sizes, answers with a diameter once and with a null the other time. What is the lesson for a procurement note?', '["The vendor list has to be widened, because a family that returns null at the tighter specification has been offered the wrong diameters for the duty it carries.", "The band has to be revisited, because none-feasible is the status a sweep returns once its rows fall outside the slenderness that was asked for.", "The preference is an answer to the specification as well as to the stream, so a diameter quoted without the droplet size it was cleared at is unquotable.", "The 7.000000 ft vessel is the safe order in both cases, since a row that is feasible at one specification stays feasible and only its reason list changes."]'::jsonb, 2, 'The AGBAMI family prefers 7.000000 ft at 500.000000 micron and returns null with none-feasible at 150.000000 micron. Every row keeps its length and slenderness between those two runs, and the 7.000000 ft row is inRange true in both.'),
  ('separation', 'advanced', 'module', 'm06-the-expert-reading', 12, 'A report gives the AGBAMI oil residence as 300.0000 s and the ERHA flare setback as 64.6458 m. What is the difference in what those two figures are worth?', '["One is measured to four decimals and one to six, which is the convention that tells a reader which figures came from the engine and which were derived on the page.", "One is held for the literature because the settling packaging is unchecked, and one is a computed setback that no held assumption feeds into at any point.", "One belongs to the vessel and one to the plot, so the two are reported by different studios and there is no basis on which to compare their worth.", "One is the 5.000000 minutes of retention typed in and read back, and one is computed from a heat release of 828000.0000 kW."]'::jsonb, 3, 'Under the proportional split the residences are the retention times in seconds, which is why this course does not grade them. A setback moves when its duty moves.'),
  ('separation', 'advanced', 'module', 'm06-the-expert-reading', 13, 'A dashboard renders null preferred diameters, null retention phases and a null pass as blank cells. What is the common risk?', '["Each blank is a finding with a reason behind it, and a blank invites a reader to fill it in by eye with the nearest row, the phase they expected or a green tick.", "Each blank is a value the engine could not compute, so the calculation has to be re-run with the missing input supplied by whoever owns it before the report can be issued at all.", "Each blank means a refusal was thrown upstream, and a thrown refusal names the input it wants while a blank cell does not.", "Each blank is a rounding artefact from printing a number below the precision the field is reported at."]'::jsonb, 0, 'A null preferred diameter carries none-feasible or none-in-band, a null retentionPhase says no contest was held, and a null pass carries nothing-checked. Each is an answer.'),
  ('separation', 'advanced', 'module', 'm06-the-expert-reading', 14, 'Four things in this course are held for the literature and one is a stated convention. What makes the Stokes constant different from the other four?', '["It is an engine constant rather than a table value, and an engine constant cannot be replaced by a site standard the way the spacing figures can, which is what marks the two kinds of unchecked figure apart.", "Its disagreement has been measured and stated at 1.004184 on every case and in the same direction, so the size of the gap travels with the number.", "It has been checked against the literature and the other four have not, which is why the field form of 1.78e-6 is the one the standards write.", "It changes no answer, since 0.044500 ft/s and 0.044686 ft/s round to the same figure at the precision vessel work is printed to."]'::jsonb, 1, 'The held items are the K derating with its floor, the borrowed settling velocity, the API 521 labels and the spacing table. None of the five is an answer, and only one of them has its error bar written down.'),
  ('separation', 'advanced', 'module', 'm06-the-expert-reading', 15, 'A handover writes 350 psi for the AGBAMI operating pressure and reports the interface to the nearest inch. What conventions has it broken?', '["Pressures are always reported as absolute in this course, and lengths are reported to four decimals in the same way as metres, kilowatts and seconds on every page of a report.", "Counts are whole numbers and everything else carries six decimals, so both the pressure and the interface needed six before the handover could be accepted.", "Gauge and absolute pressures are never written as though they were one quantity, and vessel work prints to six decimals, so the interface is 3.049149 ft.", "Nothing is broken, since 350.000000 psig and 3.049149 ft are the engine figures and a handover may round either of them for a reader."]'::jsonb, 2, 'AGBAMI runs at 350.000000 psig, which is a gauge pressure. Metres, kilowatts and seconds print to four decimals and counts are whole numbers, so the precision itself says what kind of quantity is being read.'),
  ('separation', 'advanced', 'final', null, 1, 'On lowLevelSmallOilDropCarryunder the retired chord rule handed the carryunder check a water layer of 0.617770 ft where the exact interface sits at 1.249328 ft. What was that worth on that one case?', '["The rising oil drop was timed across less than half the water the drum holds, so the crossing came back shorter than the vessel makes it, and the reported verdict still did not move.", "The drop was timed across more water than the drum holds, so the check was the conservative one and the vessels it failed would in fact have separated.", "The reported carryunder verdict on that case went from false to true, which is the disagreement that exposed the chord rule in the first place.", "Nothing on that case, because the retired layer was divided into the retention volume and the droplet checks always read the exact interface."]'::jsonb, 0, 'Every retired figure sits below its exact one and the direction never varies. The oil layer on the same case is 1.750672 ft against a retired 1.544424 ft, thin the same way.'),
  ('separation', 'advanced', 'final', null, 2, 'AGBAMI at 10.000000 ft needs 12.311666 ft of length, and the same 10.000000 ft diameter appears in the family as a row of slenderness 1.231167. What does that pairing tell a reader about the vessel the tier has been sizing?', '["It is the preferred vessel of the family, since the studio sized the stream at 10.000000 ft and the sweep confirms that choice at a slenderness of 1.231167.", "It is infeasible, because a slenderness of 1.231167 is outside the band.", "It is a working drum that the band of 3.000000 to 5.000000 excludes on shape alone, and the family prefers 7.000000 ft instead.", "It is a different vessel from the one the family swept."]'::jsonb, 2, 'The 10.000000 ft row is feasible with ld-out-of-band alone at 12.311666 ft of length. The preferred row is 7.000000 ft at 25.125850 ft and a slenderness of 3.589407.'),
  ('separation', 'advanced', 'final', null, 3, 'Tighten the AGBAMI water specification to 150.000000 micron and the whole family returns preferred null with status none-feasible. Which two facts have to be put together to explain that?', '["The band of 3.000000 to 5.000000 excludes the rows that clear the tighter specification, and the sweep reports none-feasible whenever the surviving rows are out of band.", "A droplet verdict gates feasibility, and at 0.001575 ft/s the drop needs 1238.6620 s against 300.0000 s of residence in the vessel the retentions size.", "Every row lengthens under the tighter specification until its slenderness leaves the band, and a family with no row in band reports none-feasible.", "The tighter specification lowers the gas margin on every row, and gas-capacity is the reason that gates feasibility on a three-phase family."]'::jsonb, 1, 'Each row keeps its length and slenderness and each gains water-carryover. A vessel that carries water into the oil outlet has not separated the stream, whatever its shape.'),
  ('separation', 'advanced', 'final', null, 4, 'A sweep returns preferred null and a layout returns pass null. What do the two nulls have in common, and where do they differ?', '["Both mean the calculation was refused, and they differ only in which input was missing when the refusal was raised by the engine.", "Both mean nothing qualified, and they differ in that a null preferred diameter can be recovered by widening the band while a null pass cannot be recovered at all.", "Both are rendered as blanks by any caller, and they differ in that one of them is accompanied by a warning string while the other is silent.", "Both carry a status word that says which situation produced them, and one is about vessels while the other is about comparisons that were never made."]'::jsonb, 3, 'preferredStatus reads none-feasible or none-in-band; passStatus reads nothing-checked. A blank cell loses the distinction, and the two nulls call for different work.'),
  ('separation', 'advanced', 'final', null, 5, 'worstAbsolute on ERHA is 43.8223 m short of a table figure of 90.0000 m. What has to be said about that finding when it is escalated?', '["That the requirement behind it is a recorded table value with no source checked, so the shortfall is real and the distance it is measured against is a figure a site standard may replace.", "That the shortfall is the largest on the plan and the requirement is computed from the flare duty of 828000.0000 kW.", "That the pair also appears in the relative ranking, where 0.486914 is the largest fraction reported.", "That the figure is provisional because complete is false on that plan."]'::jsonb, 0, 'The same station carries a computed flare setback of 64.6458 m that moves with its duty. A breach against a table figure and a breach against a computed setback are findings of different kinds.'),
  ('separation', 'advanced', 'final', null, 6, 'A three-phase verdict clears by 111.4796 s against 300.0000 s. How does the stated Stokes convention of 1.004184 bear on that result?', '["It widens the crossing time to the oracle figure, which is the value any published verdict should be quoted at once the field form has been converted.", "It halves the margin, since the ratio applies to the velocity and the crossing time goes as the square of it in the field form of the law.", "It does not change the verdict, because four parts in a thousand of either figure is nowhere near the gap between them.", "It makes the verdict unquotable, since the constant is unchecked."]'::jsonb, 2, 'The convention matters only where a crossing time and a residence time nearly meet. Its size is stated so that a gate on droplet settling can hold a tolerance wider than it.'),
  ('separation', 'advanced', 'final', null, 7, 'A row in a sweep is infeasible with reason gas-capacity. How much of that verdict rests on the held Souders-Brown packaging?', '["All of it, since the margin is the gas velocity over the Souders-Brown velocity and both halves of that ratio come from the held packaging.", "None of it and none of the gas length either, because the capacity rule and the length requirement are computed from the gas area rather than from a settling velocity.", "Only the sign of it, because the packaging decides which side of 1 the margin falls on.", "The margin comparison itself is a real result; the gas LENGTH that the same packaging produces is the part that is held."]'::jsonb, 3, 'gasOverloaded6ftGasControls runs 2.829421 ft/s against 0.500000 ft/s for a margin of 0.176715. The honest reading of a gas-controlled horizontal vessel today is that the vessel is gas overloaded.'),
  ('separation', 'advanced', 'final', null, 8, 'Put the three-phase steps in the order the engine performs them.', '["The interface is placed first from the liquid level, the layers follow from it, the retentions then set the length, and the verdicts are taken against the retention times.", "The retentions give the share, the share gives an area, the area inverts to an interface, the layers follow, and the verdicts come last because they need the sized vessel.", "The verdicts are taken first to establish feasibility, then the share and the interface, and the length is computed last from whichever phase controlled.", "The length comes first from the liquid retention volume, the areas follow from it, and the share and the interface are read back from the areas."]'::jsonb, 1, 'AGBAMI holds 0.516129 of its liquid area as water, which places the interface at 3.049149 ft under 1.950851 ft of oil, and the verdicts are compared against residences the length produced.'),
  ('separation', 'advanced', 'final', null, 9, 'Two published layouts sit either side of the line: s3SkippedItemPassesButIncomplete reports complete false with pass true, and s3ZeroRequirementPairOnly reports complete true with pass null. What does the pair establish?', '["That the two fields are independent: one cleared every comparison it made while an item was skipped, and the other was fully judged with nothing in it to clear.", "That pass is computed only where complete has come back true, so the pass true on the first case is the residue of a verdict the engine ought to have withheld once it knew an item on the plan had been skipped.", "That a zero-requirement pair leaves a layout incomplete, which is the reason the second case comes back with pass null rather than with the pass true that its single unbreached pair would otherwise have earned it.", "That a skipped item is the only thing able to make complete false, so the 12 unknown type pairs that ERHA reports beside its 69 checks leave the complete flag on that plan exactly where it stood."]'::jsonb, 0, 'The first is checked 3 with one item whose coordinates could not be read. The second is checked 0 with one zero-requirement pair, complete true and passStatus nothing-checked.'),
  ('separation', 'advanced', 'final', null, 10, 'Two retired behaviours failed open in different parts of the engine: droplet verdicts on a NaN gravity, and a layout that passed with nothing checked. What is the shared shape?', '["A number computed from an input that was out of its domain, which is why both were repaired by adding a domain check on the input rather than on the output.", "A default substituted for a missing figure, which is why FC1-0 replaced both defaults with refusals that name the input they want.", "An absence of information rendered as a positive result, which is quiet, where a defect that fails closed announces itself the first time somebody runs it.", "A boolean returned where a status word was needed, which is why both now return null with a reason attached to them."]'::jsonb, 2, 'waterCarryover false is the word for a vessel that passed, and pass true on s3AllUnplacedNothingChecked was reported beside checked 0.'),
  ('separation', 'advanced', 'final', null, 11, 'A report quotes a preferred diameter of 7.000000 ft for ABANA-2 and a pass true for the plot it will stand on. What is missing from each half?', '["The slenderness of 4.342025 and the count of 69 checks, which are the two figures a reviewer compares the headline answers against on any package.", "The band the preference was taken in with its status word, and the completeness reading beside the pass.", "The droplet specification and the datum of the plan, because a preference and a distance are both meaningless without the reference they were taken against.", "The reason list on the preferred row and the zero-requirement count, since those two are what turn a bare answer into a finding somebody can act on."]'::jsonb, 1, '7.000000 ft in a band of 3.000000 to 5.000000 and a null in a band of 4.000000 to 5.000000 are two honest answers, and a pass with complete false was judged on the comparisons that could be made.'),
  ('separation', 'advanced', 'final', null, 12, 'Pinning the AGBAMI water share at 0.300000 returns 8.510368 ft for the oil and 21.181362 ft for the water, and names the water in retentionPhase. What does that field add to the two lengths?', '["It names the phase whose retention time was typed as the longer of the two, which restates an input the caller already had.", "It names the phase that will leave through the wrong outlet first, so water there is the carryover verdict under another name.", "It records that the split was pinned rather than proportional, which is why a proportional run leaves it null.", "It names the phase whose retention bought the reported 21.181362 ft, so anyone shortening the drum knows whose holding time is being spent."]'::jsonb, 3, 'The two lengths say how long each phase wants the vessel to be. The field says which of them won, and a proportional run leaves it null because the two agree inside 1e-9.'),
  ('separation', 'advanced', 'final', null, 13, 'Why does complete come back false on almost any real plot, and what should a reviewer do with that?', '["The spacing table has no entry for a flow meter, a skid, a pig launcher or a booster package, so one modern item produces unknown pairs; the reading is to treat complete as a pointer at the skipped list and the unknown pairs and then judge whether the remainder matters.", "The layout check counts only positive requirements, so a plot with many zero-scored valve pairs is reported as incomplete until those pairs are given a distance.", "Any plan with a radiation source produces a skipped item, because a source has to be placed twice, once as an item and once as a duty.", "Complete is false whenever any comparison fails, so a plot with breaches on it can never be reported as complete."]'::jsonb, 0, 'ERHA reports 12 unknown pairs from one skid. Two skipped items that are a spare tank and a redundant source are a different remainder from two that are the flare and the control room.'),
  ('separation', 'advanced', 'final', null, 14, 'Four items in this course are held for the literature. Which of the following is one of them?', '["The DAK correlation for the z factor, which is why the engine refuses a reduced temperature outside 1.000000 to 3.000000 rather than extrapolating into it.", "The exact inversion of the segment area to an interface depth, which is bisected 100 times and has not been checked against a closed form solution.", "The horizontal use of the Souders-Brown velocity as the droplet settling velocity in the gas length requirement.", "The retention-proportional split of the liquid cross-section."]'::jsonb, 2, 'The four are the K derating with its 0.120000 floor, the borrowed settling velocity, the API 521 labels and the spacing table figures. A held item may be taught as a limit and never as an answer.'),
  ('separation', 'advanced', 'final', null, 15, 'At 150.000000 micron the AGBAMI 7.000000 ft row reads inRange true, feasible false, reasons water-carryover. What does that combination say to a designer?', '["The band is wrong for this duty, because a row that is in range and infeasible is the signature of a band that admits vessels the family cannot deliver.", "The shape is right and the separation is not, so the work is on the stream, the specification or the internals rather than on the band.", "The row is the one to order, since it is the only row still in range.", "The sweep is inconsistent, because a row cannot be in band and infeasible."]'::jsonb, 1, 'inRange and feasible are independent. Every row in that family carries water-carryover, so preferred is null with status none-feasible whatever the band says.'),
  ('separation', 'advanced', 'final', null, 16, 'A row carries reasons water-carryover and ld-out-of-band. Which objection can be answered by changing an input to the sweep, and which cannot?', '["Both can be answered by changing an input, since the droplet specification is as much an input to the sweep as the band is and either one moves the reason list.", "Neither can be answered by changing an input, because both reasons are computed from the stream and the drum and neither depends on anything the caller supplies.", "The carryover can be answered by widening the band until the row falls outside it, and the slenderness objection cannot be answered at all.", "The band is an input and can be argued with; the carryover is a statement about the vessel."]'::jsonb, 3, 'Widening a band can move a preference between qualifying vessels and can remove a preference, and it can never make an infeasible row feasible.'),
  ('separation', 'advanced', 'final', null, 17, 'A works order lists the two ERHA rankings and a set of droplet verdicts. Which statement about reporting holds for both?', '["A single headline answer is not enough in either place: one ranking hides the other, and one verdict without its droplet size hides the specification it was taken at.", "Both should be reported as fractions, since a shortfall of 0.597753 and a crossing time against a residence are both ratios at heart.", "Both should be escalated on the largest absolute figure, which is 43.8223 m on the plot and 1238.6620 s in the vessel.", "Both are provisional until the held items behind them are read against the literature."]'::jsonb, 0, 'worstAbsolute names the flare pair and worstRelative the pump pair, and waterCarryover false at 500.000000 micron becomes true at 150.000000 micron on the same drum.'),
  ('separation', 'advanced', 'final', null, 18, 'Which figure in an Expert package would move if the duty behind it moved?', '["The table requirement of 90.0000 m between a flare and a control room, which is scaled by the engine from the heat release of the flare it is measured against.", "The flare setback of 64.6458 m, which is computed from 828000.0000 kW of heat release.", "The oil residence of 300.0000 s under the proportional split, which is recomputed from the vessel each time the retention volume changes.", "The spacing of 3.000000 m between two pumps, which the engine raises with the rate the pumps carry."]'::jsonb, 1, 'A computed figure moves when its duty moves and a copied figure never moves. The 21 zero-requirement pairs on ERHA are table figures of 0.000000 m for the same reason.'),
  ('separation', 'advanced', 'final', null, 19, 'A three-phase family is swept and the engineer widens the band to bring in more rows. On which of the two null statuses can that possibly help?', '["none-feasible, where a wider band admits rows the narrow one excluded and one of them may clear the verdicts once it is judged.", "Both of them, since a wider band changes the reason lists and a row whose only remaining reason is removed comes back feasible.", "none-in-band, where feasible vessels exist and the band is excluding them on shape.", "Neither of them, because the band is compared against a slenderness and a slenderness cannot be changed by an input at all."]'::jsonb, 2, 'The AGBAMI family at 500.000000 micron in a band of 4.000000 to 5.000000 is all feasible and all out of band. The same family at 150.000000 micron is infeasible in any band.'),
  ('separation', 'advanced', 'final', null, 20, 'The ERHA bund gives 59.5294 m from the pool centre and 50.5294 m from the pool edge. Why does the difference of 9.0000 m matter to a layout check?', '["The two figures apply to different allowables, so a check run against 50.5294 m is using a level the site standard has not approved for continuous exposure.", "The edge figure is the conservative one, so a check run against the centre figure would report breaches that the plan does not actually have on it.", "The difference is the flame height correction, which is applied only where the point source model is being used inside the flame.", "The layout check measures centre to centre, so passing it the edge figure makes it short by half the bund."]'::jsonb, 3, 'That was the defect the Suite layer carried. The pool is 18.000000 m across and the tank icon on the plan is the pool centre, so every pair measured against the bund was handed a requirement 9.0000 m too small.'),
  ('separation', 'advanced', 'final', null, 21, 'A vessel is sized, its verdicts clear and its plot reports pass true with complete false. What may be concluded?', '["That the comparisons somebody was able to make all cleared, and that the review has a remainder which has to be read before the package is signed.", "That the plot is acceptable, since pass is the field that reports the result and complete reports only how the review was carried out by whoever ran it.", "That nothing may be concluded, because a plan that is not complete has not been judged and its pass field is not meaningful.", "That the vessel may be ordered and the plot re-run, since a pass on an incomplete plan is always superseded by the next run."]'::jsonb, 0, 's3SkippedItemPassesButIncomplete reports 3 checks cleared with one item skipped for bad coordinates. The skipped list is the place to look before signing.'),
  ('separation', 'advanced', 'final', null, 22, 'On ABANA-2 the band widens from 3.000000 to 5.000000 out to 3.000000 to 7.000000 and the preference holds at 7.000000 ft. What would have happened under the retired rule, and why does that matter beyond the sweep?', '["It would have held at 7.000000 ft as well, since the retired rule also compared rows by diameter once more than one of them was inside the band.", "It would have moved to the 6.000000 ft row, which cannot carry its gas, so a preference about shape would have changed an engineering answer.", "It would have returned null, because the retired rule refused to answer when a band change brought a new row into range.", "It would have moved to the 8.000000 ft row, which is feasible and which comes into range as the band widens toward its slenderness of 2.908817."]'::jsonb, 1, 'The 6.000000 ft row is inRange true, feasible false, reasons gas-capacity at that band. A rule that takes the first row in band lets an input about shape overrule a physical test.'),
  ('separation', 'advanced', 'final', null, 23, 'One figure in a proportional three-phase result was typed into the input form before the run and printed back out after it. Which one?', '["The interface of 3.049149 ft, which is the depth the water share of 0.516129 was pinned at by the person who set the controller.", "The water share of 0.516129, which is the water cut of the stream arriving at the inlet of the vessel.", "The oil residence of 300.0000 s on the proportional AGBAMI case.", "The requirement of 12.311666 ft, which is the length that was typed into the sweep as the vessel the vendor had quoted."]'::jsonb, 2, 'The proportional split gives both phases the same length, so the residences come back as the 5.000000 minutes and 8.000000 minutes that were typed in.'),
  ('separation', 'advanced', 'final', null, 24, 'A reviewer asks why the course teaches the K derating at all if it is held. What is the answer?', '["Because it moves every dimension below it and a reader has to know what produced the number, while the number itself carries the uncertainty of a rule of thumb rather than the precision of its six decimals.", "Because the derating is checked at the table values and unchecked only at the floor, so the taught part is the half that has a source behind it.", "Because a held item becomes an answer once a course teaches it, which is how the four held items are cleared one by one.", "Because the derating is the only part of the chain a vendor cannot override, so a designer has to work it by hand."]'::jsonb, 0, 'A vertical mesh pad falls from 0.350000 to 0.300000 at 600.000000 psig, and the settling velocity, the diameter, the margin and the feasibility of every row move with it.'),
  ('separation', 'advanced', 'final', null, 25, 'A vessel is sized behind a mist extractor whose derated K sits a little above the floor, and the family it is swept in returns a preferred diameter. What has to travel with that preference?', '["Nothing beyond the band it was swept in, since the K enters through the settling velocity and the gas margin printed on each row has already carried it into every feasibility flag the family reports.", "The oracle ratio of 1.004184, because a K taken from the derating rule sits four parts in a thousand below the SI derivation in the same way the field form of Stokes law does on every published case.", "The floored flag, which comes back true on any K this close to 0.120000 and marks the value as chosen rather than computed.", "That the K is a rule of thumb held for the literature: verticalNoneAt650psig sits 0.005000 above the floor of 0.120000 with nearFloor true, and the gas margin on every row came from it."]'::jsonb, 3, 'verticalNoneAt650psig returns K 0.125000 with derated true and floored false, which is 0.005000 above the floor and 50 psi of operating pressure away from being floored. The derating and the floor are held, so the uncertainty of the rule travels with every row the family reports.'),
  ('separation', 'advanced', 'final', null, 26, 'A carryunder result and a preferred diameter both come from a run made before FC1-0. What is the right handling of each?', '["Keep the carryunder result and re-run the preference, since the droplet arithmetic was never in question and only the sweep rule changed in the FC1-0 repairs.", "Re-run both, because one was measured against a chord-rule layer and the other may be a vessel that was merely first in the list or could not carry its gas.", "Re-run the carryunder result and keep the preference, since a preferred diameter is a recommendation rather than a computed figure and does not expire.", "Keep both and mark them provisional, since neither repair changed a number and both changed only how the answer is reported to a caller."]'::jsonb, 1, 'Neither needs new physics. They need the same cases run again through the repaired engine and the answers compared.'),
  ('separation', 'advanced', 'final', null, 27, 'What makes the pairing of the two ERHA rankings a judgement rather than a calculation?', '["The rankings are computed from different quantities and the engine combines them into a single index that a reviewer then interprets before any works order is written.", "Only one of the two is computed, since worstRelative is a fraction of a table figure and a table figure is recorded rather than calculated, with no source checked.", "The engine returns both and names neither the worst, so somebody has to decide whether 43.8223 m of missing plot or 0.597753 of a small requirement leads the works order.", "The rankings disagree only on plans where a computed setback and a table figure are both breached, so the judgement is about which requirement to trust."]'::jsonb, 2, 'A fraction has no size in it and a shortfall in metres has no sense of proportion in it. Two pumps 1.7933 m short are a day of steelwork; a control room 43.8223 m short is a different plot.'),
  ('separation', 'advanced', 'final', null, 28, 'A three-phase sizing call is made with no oil viscosity. What comes back, and what would have come back before FC1-0 had the oil gravity been the missing input instead?', '["A SeparatorInputError naming muOilCp comes back now, and a missing gravity used to produce two droplet verdicts of false from comparisons against NaN.", "An error object naming the viscosity comes back now, and a missing gravity used to throw on sgOil in the same way, so the two inputs have always been handled identically.", "A vessel sized without droplet verdicts comes back now, and a missing gravity used to do the same thing.", "A refusal comes back in both cases, since the repair made every missing input throw and the two behave identically."]'::jsonb, 0, 'A verdict for an input the engine could not read is a verdict that says nothing, and false is the word this engine uses for a vessel that passed.'),
  ('separation', 'advanced', 'final', null, 29, 'Why can a three-phase row be infeasible while its two-phase neighbour at the same diameter is not?', '["Because a three-phase row is sized from two retention volumes rather than one, so its length is always the larger and its slenderness always further outside the band.", "Because the gas capacity rule is applied to the gas space above two liquids rather than one, which lowers the margin on any three-phase row at a given diameter.", "Because the interface inversion adds an error to the length.", "A droplet verdict gates feasibility on a three-phase row and there is no such verdict on a two-phase one."]'::jsonb, 3, 'The reason vocabulary is gas-capacity, ld-out-of-band, water-carryover and none. water-carryover appears on the AGBAMI family at 150.000000 micron and on horizontal3DropletVerdictsGateFeasibility.'),
  ('separation', 'advanced', 'final', null, 30, 'The distance cases agree exactly across three methods and the Stokes cases disagree by a constant. Why are both results useful?', '["Exact agreement proves the coordinates on the plan are correct, and the constant ratio proves the field form of Stokes law is the one the standards intend.", "Exact agreement says the distance arithmetic is sound at site scale, and a constant ratio of 1.004184 rules out a slip and points straight at a packaged constant.", "Exact agreement shows the goldens are measurements, and the constant ratio shows the engine carries a defect that is small enough to leave in place.", "Both show the oracle and the engine were written by the same method, which is what a golden set is built to demonstrate."]'::jsonb, 1, 'A slip in the working would wander with the inputs. The distance figures are 89.4099 m, 489.2584 m, 55.5975 m and 1111.9508 m across haversine, Vincenty and the chord.'),
  ('separation', 'advanced', 'final', null, 31, 'A designer lowers the interface on AGBAMI to cure a carryover and then re-runs the sweep. Which two results have to be read again?', '["The gas margin and the slenderness, because moving the interface changes the gas area and therefore the length the drum needs once the level has moved with it.", "The retention lengths alone, because the layers set the two phase lengths and nothing else in the result depends on where the interface sits once the drum is fixed.", "Both droplet verdicts, because the water layer thickened while the oil layer thinned, and the family, because a row whose verdict turns changes its feasibility.", "The preferred diameter alone, because a verdict that turns removes a row from the family and the preference is the only field that can move."]'::jsonb, 2, 'AGBAMI holds 1.950851 ft of oil over 3.049149 ft of water and the two verdicts pull in opposite directions. A row carrying water-carryover comes back feasible false.'),
  ('separation', 'advanced', 'final', null, 32, 'What does a sweep report about a row it has judged infeasible?', '["Everything it reports about any other row: the length it would need for its liquid, its slenderness, both flags and the full reason list, because a reader is entitled to see the shape of the problem.", "Only the reason it failed, since a length for a vessel that does not work would be misleading in a table a reviewer may read quickly.", "The length and the reason, but no slenderness, since a slenderness is meaningful only for rows that could be ordered.", "A null row with its diameter, which is how the sweep marks a vessel that cannot carry the duty it was given."]'::jsonb, 0, 'On ABANA-2 the 5.000000 ft row reports 59.572579 ft at a slenderness of 11.914516 with both flags false. A reader who filters the sweep loses the fact that the two smallest diameters failed on gas.'),
  ('separation', 'advanced', 'final', null, 33, 'On gasOverloaded6ftGasControls the retention asks 0.689497 ft and the vessel comes back at 16.976527 ft with the controlling requirement gas. If the literature check moves the borrowed settling velocity, which of those two figures moves with it?', '["Both of them, since the borrowed settling velocity fixes the liquid area that the retention volume is divided by, so a move in the packaging carries 0.689497 ft along with the gas figure.", "16.976527 ft, because a gas-controlled length is computed through the velocity held for the literature, while 0.689497 ft is a volume over an area.", "0.689497 ft only, because a retention length is where a settling velocity enters a three-phase vessel and a gas length is fixed once the bore and the level are typed.", "Neither of them, because the case is published as a golden and a golden expectation is frozen by the file it lives in whatever the literature check later decides."]'::jsonb, 1, 'A gas length is a velocity ratio carried onto a height, so it reads the borrowed velocity twice over. A retention length reads a volume and an area and no velocity at all.'),
  ('separation', 'advanced', 'final', null, 34, 'The ERHA plan carries one chemical injection skid, a tank whose coordinates cannot be read and a radiation source that was never placed. What does the layout check do with the three of them?', '["It refuses the whole layout with an error object, because a list containing an item it cannot place is not a list of placed items in the sense the check requires.", "It scores the unknown pairs at zero so the plan can be judged, and it counts the two skipped items among the zero-requirement pairs for the same reason.", "It drops the three items and reports complete true on what remains, since a plan judged on the items that were placed is complete for those items.", "It records 12 unknown type pairs and 2 skipped items with their reasons, and it judges the rest of the plan."]'::jsonb, 3, 'ERHA reports exactly that and still makes 69 comparisons. The skipped list does not invalidate the checks that were made; it says the review has a remainder.'),
  ('separation', 'advanced', 'final', null, 35, 'Which pair of figures in an Expert answer must never be quoted as though they were the same quantity?', '["The interface of 3.049149 ft and the water layer of 3.049149 ft, which are printed as the same number and describe different things in the engine''s return.", "The liquid level of 0.500000 and the water share of 0.516129, which are both fractions and are both applied to the cross-section.", "The gas-liquid chord of 10.000000 ft and the oil-water interface of 3.049149 ft, one a width across the drum and one a depth from the bottom of it.", "The length of 12.311666 ft and the retention length of 12.311666 ft, which agree on a proportional case and diverge on a gas-controlled one."]'::jsonb, 2, 'Both are horizontal lines in the same drawing, which is why the chord was taken for the interface before FC1-0. Neither is available as a substitute for the other.'),
  ('separation', 'advanced', 'final', null, 36, 'What does the retired sweep rule and the retired layout rule have in common?', '["Each returned a confident answer where the honest answer was that nothing qualified: a diameter where no row was feasible, and a pass where no comparison had been made.", "Each ignored an input the caller had supplied, the band in one case and the spacing table in the other.", "Each reported the right answer in the wrong field, which is why both repairs were changes to the return shape.", "Each failed closed, so both produced alarms that sent engineers back to re-run cases that were sound."]'::jsonb, 0, 'verticalNoneFeasible preferred 3.000000 ft under the retired rule and returns none-feasible now. s3AllUnplacedNothingChecked reported pass true with checked 0.'),
  ('separation', 'advanced', 'final', null, 37, 'AGBAMI as sized holds the oil 300.0000 s, and a 500.000000 micron water drop crosses the 1.950851 ft oil layer in 111.4796 s. A specification of 250.000000 micron settles that drop at 0.004375 ft/s. What happens to waterCarryover?', '["It stays false, because 0.004375 ft/s still carries the drop through 1.950851 ft inside the 300.0000 s the oil is held.", "It turns true, because a quarter of the speed is four times the 111.4796 s crossing and the oil is held only 300.0000 s.", "It turns true and takes oilCarryunder with it, because one specification governs both drops and 217.8010 s lengthens in the same proportion.", "It is unchanged and the drum lengthens instead, because the engine raises the oil retention until the crossing fits inside it."]'::jsonb, 1, 'Velocity goes as the square of the diameter, so halving the drop quarters the speed and quadruples the crossing. At 150.000000 micron the same reading gives 1238.6620 s against 300.0000 s and the warning fires.'),
  ('separation', 'advanced', 'final', null, 38, 'What is the honest way to report a vessel sized with a vendor K?', '["State the K and the derated table value beside it, since the engine returns both on an override so that a reviewer can compare them at that pressure.", "State the K alone, since an override wins outright and the table value at that pressure has no bearing on the vessel that was sized from it.", "State the K and the floor of 0.120000, since the floor is the only part of the table that still applies once an override has been supplied to the engine.", "State the K, the pressure it was quoted at, and that nothing reconciled it against the table."]'::jsonb, 3, 'An override returns source typed with derated and floored both false, and no warning is raised when a typed K sits far from the table. A vendor K of 0.9 would be taken silently.'),
  ('separation', 'advanced', 'final', null, 39, 'A layout reports 69 checks and a sweep reports six rows. What do the two counts have in common as headline numbers?', '["Each is a count of results that passed, so the two can be compared directly against the counts of what failed.", "Each is fixed by the engine rather than by the caller, so the two are the parts of a package a reviewer does not have to check.", "Each depends on what was put in front of the engine, so a bigger count is not a better review or a better family.", "Each is reported without a status word, which is why both need a second field beside them before they can be read."]'::jsonb, 2, 'Adding relief valves adds pairs to a plan and adding diameters adds rows to a family. ERHA carries 21 zero-requirement pairs beside its 69 checks.'),
  ('separation', 'advanced', 'final', null, 40, 'The retired Suite layer handed the layout check the pool setback of 50.5294 m measured from the bund edge, where the requirement at the tank is 59.5294 m. What did that cost on the crude tank to heater treater pair?', '["The pair reads 9.3696 m short of the real requirement and only 0.3696 m short of the retired one, so the defect showed as a smaller number rather than as a pass.", "The pair clears the retired figure outright at 50.1598 m against 50.5294 m, so the retired reading turned that breach into a pass and left the plot with 5 to report.", "The pair reads 9.3696 m short either way, because the half bund falls out of a shortfall measured between the same two items on the same plan.", "The pair is untouched, because a heater treater beside a tank is scored from the table at 30.000000 m rather than against a computed pool setback."]'::jsonb, 0, 'Every row of that comparison differs by the 9.0000 m half bund. Judged the retired way the plot still fails, 6 breaches against 6, so a reviewer saw 0.3696 m where the real shortfall is 9.3696 m and no change at all in the count.'),
  ('separation', 'advanced', 'final', null, 41, 'A three-phase result reports controlling liquid-retention with retentionPhase null, and a sweep row reports feasible true with ld-out-of-band. What do both pairs of fields illustrate?', '["A defect in the reporting, since a null and a reason on an otherwise clean row are both artefacts of fields that FC1-0 added and did not populate.", "An answer and its qualifier travel together: one says which contest set the length and that no phase won inside it, and one says the vessel works and is not the shape that was asked for.", "Two ways of reporting a tie, one between phases and one between a vessel and a band.", "A conflict between fields, since a controlling requirement with no phase and a feasible row with a reason each carry two statements that cannot both be true."]'::jsonb, 1, 'The proportional split makes both phase lengths agree, so no phase is named. Slenderness is a preference about shape, so ld-out-of-band alone leaves feasible true.'),
  ('separation', 'advanced', 'final', null, 42, 'Which of these would be a legitimate Expert answer of the form null with a reason?', '["A vessel length on a drum whose liquid level was given as 1, reported as null because the level lies outside its range.", "A settling velocity for a droplet with no viscosity, reported as null with a reason naming the missing viscosity.", "A preferred diameter on a family where every row carries water-carryover, reported as null with status none-feasible.", "An interface depth on a case where the water area exceeds the circle, reported as null with a reason about the area."]'::jsonb, 2, 'The AGBAMI family at 150.000000 micron returns exactly that. A liquid level of 1 throws a SeparatorInputError, and a droplet with no viscosity and an area outside the circle come back as objects carrying an error string.');
